let currentLang = localStorage.getItem('app_lang') || 'ku_badini';
if (currentLang === 'ku') currentLang = 'ku_badini';

const TRANSLATIONS = {
    ku_badini: LANG_KU,
    ku_sorani: LANG_KU_SORANI,
    ar: LANG_AR,
    en: LANG_EN
};

function t(key, fallback = '') {
    if (!TRANSLATIONS[currentLang]) currentLang = 'ku_badini';
    let val = TRANSLATIONS[currentLang][key] || TRANSLATIONS['ku_badini'][key] || fallback || key;

    // Dynamically filter out Computer (index 10) and Psychology (index 11) for Primary/Secondary stages
    if (key === 'specializations' && Array.isArray(val)) {
        const schedule = allSchedules[activeScheduleName];
        const schoolType = schedule?.settings?.milakData?.schoolType || 'سه‌ره‌تایی 1-6'; // default to primary
        if (schoolType.includes('سه‌ره‌تایی') || schoolType.includes('ئامادەیی') || schoolType === 'ئامادهیی') {
            return val.filter((item, idx) => idx !== 10 && idx !== 11);
        }
    }
    return val;
}

function translateStoredData(newLang) {
    if (!allSchedules) return;
    const targetLangObj = TRANSLATIONS[newLang];
    if (!targetLangObj) return;

    const translateValue = (val, arrayKey) => {
        if (!val) return val;
        for (const langKey in TRANSLATIONS) {
            const arr = TRANSLATIONS[langKey][arrayKey];
            if (arr) {
                const idx = arr.indexOf(val);
                if (idx !== -1) {
                    return targetLangObj[arrayKey][idx] || val;
                }
            }
        }
        return val;
    };

    for (const scheduleName in allSchedules) {
        const schedule = allSchedules[scheduleName];
        if (schedule.teachers) {
            schedule.teachers.forEach(teacher => {
                if (teacher.certificate) teacher.certificate = translateValue(teacher.certificate, 'certificates');
                if (teacher.jobTitle) teacher.jobTitle = translateValue(teacher.jobTitle, 'job_titles');
                if (teacher.specialization) teacher.specialization = translateValue(teacher.specialization, 'specializations');

                if (teacher.subjects) {
                    teacher.subjects.forEach(subj => {
                        if (subj.name) subj.name = translateValue(subj.name, 'specializations');
                    });
                }

                if (teacher.classes) {
                    for (const col in teacher.classes) {
                        const classObj = teacher.classes[col];
                        const newClassObj = {};
                        for (const subjName in classObj) {
                            const newSubjName = translateValue(subjName, 'specializations');
                            newClassObj[newSubjName] = classObj[subjName];
                        }
                        teacher.classes[col] = newClassObj;
                    }
                }
            });
        }

        if (schedule.settings && schedule.settings.workDays) {
            schedule.settings.workDays = schedule.settings.workDays.map(day => translateValue(day, 'work_days'));
        }

        if (schedule.timetables) {
            const newTimetables = {};
            for (const day in schedule.timetables) {
                const newDay = translateValue(day, 'work_days');
                newTimetables[newDay] = schedule.timetables[day];

                for (const col in newTimetables[newDay]) {
                    for (const period in newTimetables[newDay][col]) {
                        const cell = newTimetables[newDay][col][period];
                        if (cell && cell.subject) {
                            cell.subject = translateValue(cell.subject, 'specializations');
                        }
                    }
                }
            }
            schedule.timetables = newTimetables;
        }
    }
}

function changeLanguage(newLang) {
    if (!TRANSLATIONS[newLang]) return;

    translateStoredData(newLang);

    currentLang = newLang;
    localStorage.setItem('app_lang', currentLang);

    if (typeof saveData === 'function') {
        saveData(true);
    }

    document.documentElement.lang = currentLang;
    document.documentElement.dir = (currentLang === 'en') ? 'ltr' : 'rtl';

    applyTranslations();

    if (typeof renderApp === 'function') {
        const searchInput = document.getElementById('searchInput');
        renderApp(searchInput ? searchInput.value : '');
    }
}

function applyTranslations() {
    const langObj = TRANSLATIONS[currentLang] || TRANSLATIONS['ku_badini'];

    document.querySelectorAll('[data-i18n]').forEach(el => {
        const key = el.getAttribute('data-i18n');
        if (langObj[key]) {
            const icon = el.querySelector('i');
            if (icon) {
                let textUpdated = false;
                el.childNodes.forEach(node => {
                    if (node.nodeType === Node.TEXT_NODE) {
                        node.textContent = ' ' + langObj[key];
                        textUpdated = true;
                    }
                });
                if (!textUpdated) {
                    el.appendChild(document.createTextNode(' ' + langObj[key]));
                }
            } else {
                el.innerText = langObj[key];
            }
        }
    });

    document.querySelectorAll('[data-i18n-placeholder]').forEach(el => {
        const key = el.getAttribute('data-i18n-placeholder');
        if (langObj[key]) el.placeholder = langObj[key];
    });

    document.querySelectorAll('[data-i18n-title]').forEach(el => {
        const key = el.getAttribute('data-i18n-title');
        if (langObj[key]) el.title = langObj[key];
    });

    const langSelect = document.getElementById('languageSelector');
    if (langSelect) langSelect.value = currentLang;
}

