const PREDEFINED_SUBJECTS = ['ئاین', 'كوردی', 'عربی', 'ئینگلیزی', 'بیركاری', 'زانست', 'كومه‌لایه‌تی', 'كارامه‌ی', 'ده‌روونزانی', 'كومپیوته‌ر', 'هونه‌ر', 'وه‌رزش'];
const ALL_DAYS_KURDISH = ['شەمب', 'ئێك شەمب', 'دوو شەمب', 'سێ شەمب', 'چوار شەمب', 'پێنج شەمب', 'ئەینی'];

function getTeacherTotal(teacher) {
    return (teacher.classes ? Object.values(teacher.classes).reduce((sum, classObj) => {
        return sum + Object.values(classObj).reduce((value, periods) => value + (parseInt(periods, 10) || 0), 0);
    }, 0) : 0);
}

function sortDistributionTable(mode) {
    const schedule = allSchedules[activeScheduleName];
    if (!schedule || !Array.isArray(schedule.teachers)) return;
    const sortedTeachers = [...schedule.teachers];

    const compareText = (a, b, prop) => (a[prop] || '').localeCompare(b[prop] || '', 'ar', { sensitivity: 'base' });

    if (mode === 'name') {
        sortedTeachers.sort((a, b) => compareText(a, b, 'name'));
    } else if (mode === 'total') {
        sortedTeachers.sort((a, b) => getTeacherTotal(b) - getTeacherTotal(a));
    } else if (mode === 'certificate') {
        sortedTeachers.sort((a, b) => compareText(a, b, 'certificate'));
    } else if (mode === 'specialization') {
        sortedTeachers.sort((a, b) => compareText(a, b, 'specialization'));
    } else if (mode === 'jobTitle') {
        sortedTeachers.sort((a, b) => compareText(a, b, 'jobTitle'));
    }

    schedule.teachers = sortedTeachers;
    saveData();
    renderDistributionTable(searchInput?.value || '');

    const modeLabels = {
        name: 'ناڤ',
        total: 'کۆی',
        certificate: 'بروانامه',
        specialization: 'بسپور',
        jobTitle: 'نیشانا کاری'
    };
    showToast(`خشتە هاتە رێکخستن بە ${modeLabels[mode] || 'فرز'}.`);
}

function moveTeacherRow(teacherId, direction) {
    const schedule = allSchedules[activeScheduleName];
    if (!schedule || !Array.isArray(schedule.teachers)) return;

    const filter = searchInput ? searchInput.value.trim().toLowerCase() : '';
    const visibleTeachers = filter
        ? schedule.teachers.filter(t => (t.name || '').toLowerCase().includes(filter))
        : schedule.teachers;

    const visIndex = visibleTeachers.findIndex(t => String(t.id) === String(teacherId));
    if (visIndex === -1) return;

    const targetVisIndex = direction === 'up' ? visIndex - 1 : visIndex + 1;
    if (targetVisIndex < 0 || targetVisIndex >= visibleTeachers.length) return;

    const teacherA = visibleTeachers[visIndex];
    const teacherB = visibleTeachers[targetVisIndex];

    const mainIdxA = schedule.teachers.findIndex(t => t.id === teacherA.id);
    const mainIdxB = schedule.teachers.findIndex(t => t.id === teacherB.id);

    if (mainIdxA !== -1 && mainIdxB !== -1) {
        schedule.teachers[mainIdxA] = teacherB;
        schedule.teachers[mainIdxB] = teacherA;
        saveData(true);
        renderDistributionTable(searchInput ? searchInput.value : '');
        showToast('جهێ ماموستایی هاتە گوهورین', 'success');
    }
}

function changeTeacherPosition(teacherId, newPositionStr) {
    const schedule = allSchedules[activeScheduleName];
    if (!schedule || !Array.isArray(schedule.teachers)) return;

    let targetPos = parseInt(newPositionStr, 10);
    if (isNaN(targetPos)) return;

    const mainIndex = schedule.teachers.findIndex(t => String(t.id) === String(teacherId));
    if (mainIndex === -1) return;

    targetPos = Math.max(1, Math.min(schedule.teachers.length, targetPos));
    const newIndex = targetPos - 1;

    if (mainIndex === newIndex) return;

    const [movedTeacher] = schedule.teachers.splice(mainIndex, 1);
    schedule.teachers.splice(newIndex, 0, movedTeacher);

    saveData(true);
    renderDistributionTable(searchInput ? searchInput.value : '');
    showToast('جهێ ماموستایی هاتە گوهورین', 'success');
}

async function openReorderTeachersModal() {
    const schedule = allSchedules[activeScheduleName];
    if (!schedule || !schedule.teachers || schedule.teachers.length === 0) {
        showToast('هیچ ماموستایەك نینە د ڤی خشتەیی دا.', 'warning');
        return;
    }

    const buildListHtml = () => {
        return schedule.teachers.map((t, idx) => `
            <div class="d-flex align-items-center justify-content-between p-2 mb-2 bg-body-tertiary border rounded-3 shadow-xs" data-teacher-id="${t.id}">
                <div class="d-flex align-items-center gap-2">
                    <span class="badge bg-primary rounded-circle p-2" style="width:28px; height:28px; display:inline-flex; align-items:center; justify-content:center;">${idx + 1}</span>
                    <i class="fas fa-grip-vertical text-muted drag-handle-modal me-1" style="cursor:grab;"></i>
                    <div class="text-start">
                        <strong class="text-dark-emphasis d-block">${t.name || ''}</strong>
                        <span class="small text-muted">${t.specialization || ''} ${t.certificate ? '(' + t.certificate + ')' : ''}</span>
                    </div>
                </div>
                <div class="d-flex align-items-center gap-2">
                    <label class="small text-muted mb-0">جهـ:</label>
                    <input type="number" class="form-control form-control-sm text-center fw-bold pos-input" style="width:65px;" min="1" max="${schedule.teachers.length}" value="${idx + 1}" data-teacher-id="${t.id}">
                    <div class="btn-group btn-group-sm">
                        <button type="button" class="btn btn-outline-secondary btn-sm" onclick="moveTeacherRow(${t.id}, 'up'); openReorderTeachersModal();" ${idx === 0 ? 'disabled' : ''}><i class="fas fa-chevron-up"></i></button>
                        <button type="button" class="btn btn-outline-secondary btn-sm" onclick="moveTeacherRow(${t.id}, 'down'); openReorderTeachersModal();" ${idx === schedule.teachers.length - 1 ? 'disabled' : ''}><i class="fas fa-chevron-down"></i></button>
                    </div>
                </div>
            </div>
        `).join('');
    };

    await Swal.fire({
        title: '<i class="fas fa-arrows-alt-v me-2 text-primary"></i>تعديل مكان المعلمين د جدول دا',
        html: `<div id="modal-teachers-reorder-container" style="max-height:60vh; overflow-y:auto;" class="pe-1">${buildListHtml()}</div>`,
        showCancelButton: false,
        confirmButtonText: t('btn_close') || 'داخستن',
        customClass: { popup: 'rounded-4' },
        didOpen: (modalEl) => {
            const container = modalEl.querySelector('#modal-teachers-reorder-container');
            if (container) {
                container.querySelectorAll('.pos-input').forEach(input => {
                    input.addEventListener('change', (e) => {
                        const tId = parseInt(e.target.dataset.teacherId, 10);
                        changeTeacherPosition(tId, e.target.value);
                        openReorderTeachersModal();
                    });
                });

                if (typeof Sortable !== 'undefined') {
                    new Sortable(container, {
                        animation: 150,
                        handle: '.drag-handle-modal',
                        onEnd: () => {
                            const newIds = Array.from(container.children)
                                .map(child => parseInt(child.dataset.teacherId, 10))
                                .filter(id => !isNaN(id));

                            const reordered = newIds
                                .map(id => schedule.teachers.find(t => t.id === id))
                                .filter(Boolean);

                            if (reordered.length === schedule.teachers.length) {
                                schedule.teachers = reordered;
                                saveData(true);
                                renderDistributionTable(searchInput ? searchInput.value : '');
                            }
                        }
                    });
                }
            }
        }
    });
}



// --- DOM Element Caching (will be initialized in DOMContentLoaded) ---
let searchInput, themeSwitcher, teacherModalEl, settingsModalEl;

// --- Advanced Security & Anti-Hacking Protection Utilities ---
function escapeHTML(str) {
    if (str === null || str === undefined) return '';
    return String(str)
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#039;');
}

function sanitizeInputString(str) {
    if (typeof str !== 'string') return str;
    return str
        .replace(/<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi, '')
        .replace(/javascript\s*:/gi, '')
        .replace(/data\s*:\s*text\/html/gi, '')
        .replace(/on\w+\s*=/gi, '')
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#039;');
}

function sanitizeObject(obj) {
    if (!obj || typeof obj !== 'object') return obj;
    if (Array.isArray(obj)) {
        return obj.map(sanitizeObject);
    }
    const cleanObj = {};
    for (const key of Object.keys(obj)) {
        // Anti-Prototype Pollution Protection
        if (key === '__proto__' || key === 'constructor' || key === 'prototype') continue;
        const val = obj[key];
        if (typeof val === 'string') {
            cleanObj[key] = sanitizeInputString(val);
        } else if (typeof val === 'object' && val !== null) {
            cleanObj[key] = sanitizeObject(val);
        } else {
            cleanObj[key] = val;
        }
    }
    return cleanObj;
}

function validateAndSanitizeSchedules(rawData) {
    if (!rawData || typeof rawData !== 'object') return null;
    const cleanData = sanitizeObject(rawData);
    for (const sName in cleanData) {
        const sch = cleanData[sName];
        if (sch && typeof sch === 'object') {
            if (!Array.isArray(sch.teachers)) sch.teachers = [];
            if (!Array.isArray(sch.columns)) sch.columns = [];
            if (!sch.timetables || typeof sch.timetables !== 'object') sch.timetables = {};
            if (!sch.settings || typeof sch.settings !== 'object') {
                sch.settings = {
                    principalName: 'طاهر محمود محمد',
                    studentTableRows: 6,
                    leaveTableRows: 4,
                    studentTableData: [],
                    leaveTableData: [],
                    periodsPerDay: 7,
                    workDays: ['ئێك شەمب', 'دوو شەمب', 'سێ شەمب', 'چوار شەمب', 'پێنج شەمب']
                };
            }
            if (!sch.nisab || typeof sch.nisab !== 'object') sch.nisab = {};
            if (sch.settings && !sch.settings.milakData) sch.settings.milakData = {};
        }
    }
    return cleanData;
}

const showToast = (message, icon = 'success') => {
    Swal.mixin({
        toast: true, position: 'top-start', showConfirmButton: false, timer: 3000, timerProgressBar: true,
        didOpen: (toast) => { toast.onmouseenter = Swal.stopTimer; toast.onmouseleave = Swal.resumeTimer; }
    }).fire({ icon, title: escapeHTML(message) });
};

// --- Core Data Management & Device-Isolated Silent Auto-Backup ---
const IDB_NAME = 'MamostaTimetableDeviceDB';
const IDB_STORE = 'schedulesStore';

function getIDB() {
    return new Promise((resolve) => {
        if (!window.indexedDB) return resolve(null);
        const req = indexedDB.open(IDB_NAME, 1);
        req.onupgradeneeded = (e) => {
            const db = e.target.result;
            if (!db.objectStoreNames.contains(IDB_STORE)) {
                db.createObjectStore(IDB_STORE);
            }
        };
        req.onsuccess = (e) => resolve(e.target.result);
        req.onerror = () => resolve(null);
    });
}

async function saveToIDB(dataPayload) {
    try {
        const db = await getIDB();
        if (!db) return;
        const tx = db.transaction(IDB_STORE, 'readwrite');
        tx.objectStore(IDB_STORE).put(dataPayload, 'auto_backup');
    } catch (e) {
        console.warn('Auto IDB backup warning:', e);
    }
}

async function loadFromIDB() {
    try {
        const db = await getIDB();
        if (!db) return null;
        return new Promise((resolve) => {
            const tx = db.transaction(IDB_STORE, 'readonly');
            const req = tx.objectStore(IDB_STORE).get('auto_backup');
            req.onsuccess = () => resolve(req.result || null);
            req.onerror = () => resolve(null);
        });
    } catch (e) {
        return null;
    }
}

async function loadData() {
    let rawData = localStorage.getItem('allSchedules');
    activeScheduleName = localStorage.getItem('activeScheduleName') || '';

    if (rawData) {
        try {
            allSchedules = JSON.parse(rawData) || {};
        } catch (e) {
            allSchedules = {};
        }
    } else {
        allSchedules = {};
    }

    if (Object.keys(allSchedules).length === 0) {
        const defaultName = 'خشتێ سه‌ره‌كی';
        allSchedules[defaultName] = {
            columns: [],
            teachers: [],
            nisab: {},
            settings: { principalName: 'طاهر محمود محمد', studentTableRows: 6, leaveTableRows: 4, studentTableData: [], leaveTableData: [], periodsPerDay: 7, workDays: ['ئێك شەمب', 'دوو شەمب', 'سێ شەمب', 'چوار شەمب', 'پێنج شەمب'] }
        };
        activeScheduleName = defaultName;
    }

    if (!allSchedules[activeScheduleName]) activeScheduleName = Object.keys(allSchedules)[0];

    for (const scheduleName in allSchedules) {
        const schedule = allSchedules[scheduleName];
        schedule.nisab = schedule.nisab || {};
        if (!schedule.settings) {
            schedule.settings = { principalName: 'طاهر محمود محمد', studentTableRows: 6, leaveTableRows: 4, studentTableData: [], leaveTableData: [], periodsPerDay: 7, workDays: ['ئێك شەمب', 'دوو شەمب', 'سێ شەمب', 'چوار شەمب', 'پێنج شەمب'] };
        } else {
            schedule.settings.studentTableData = schedule.settings.studentTableData || [];
            schedule.settings.leaveTableData = schedule.settings.leaveTableData || [];
            schedule.settings.periodsPerDay = schedule.settings.periodsPerDay || 7;
            schedule.settings.workDays = schedule.settings.workDays || ['ئێك شەمب', 'دوو شەمب', 'سێ شەمب', 'چوار شەمب', 'پێنج شەمب'];
            schedule.settings.milakData = schedule.settings.milakData || {};
        }
        if (schedule.settings.principalName === 'مسعود لاوند تحلو') {
            schedule.settings.principalName = 'طاهر محمود محمد';
        }
    }
    saveData();
}

let _saveDataTimeout = null;
function saveData(immediate = false) {
    const doSave = () => {
        try {
            localStorage.setItem('allSchedules', JSON.stringify(allSchedules));
            localStorage.setItem('activeScheduleName', activeScheduleName);
            saveToIDB({ allSchedules, activeScheduleName });
        } catch (e) {
            console.error('saveData error', e);
        }
    };
    if (immediate) {
        if (_saveDataTimeout) clearTimeout(_saveDataTimeout);
        doSave();
        return;
    }
    if (_saveDataTimeout) clearTimeout(_saveDataTimeout);
    _saveDataTimeout = setTimeout(doSave, 150);
}

async function handleSaveLoad(action) {
    if (action === 'save') {
        const dataStr = JSON.stringify({ allSchedules, activeScheduleName }, null, 2);
        const blob = new Blob([dataStr], { type: 'application/json;charset=utf-8' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `schedules_backup_${new Date().toISOString().slice(0, 10)}.json`;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        URL.revokeObjectURL(url);
        showToast('زانیاری هاتنه‌ هیلان.');
    } else if (action === 'load') {
        const input = document.createElement('input');
        input.type = 'file';
        input.accept = '.json, application/json, text/plain';
        input.style.display = 'none';
        document.body.appendChild(input);

        input.onchange = e => {
            const file = e.target.files && e.target.files[0];
            if (!file) {
                if (document.body.contains(input)) document.body.removeChild(input);
                return;
            }

            const reader = new FileReader();
            reader.onload = event => {
                try {
                    let content = event.target.result;
                    if (typeof content === 'string') {
                        // Strip UTF-8 BOM if present
                        content = content.replace(/^\uFEFF/, '').trim();
                    }

                    let data;
                    try {
                        data = JSON.parse(content);
                    } catch (parseError) {
                        if (typeof LZString !== 'undefined') {
                            const decompressed = LZString.decompressFromBase64(content);
                            if (decompressed) {
                                data = JSON.parse(decompressed);
                            } else {
                                throw parseError;
                            }
                        } else {
                            throw parseError;
                        }
                    }

                    // Decompress if LZString stringified payload or cloud sync string format
                    if (typeof data === 'string') {
                        try {
                            data = JSON.parse(data);
                        } catch (_) {
                            if (typeof LZString !== 'undefined') {
                                const decompressed = LZString.decompressFromBase64(data);
                                if (decompressed) data = JSON.parse(decompressed);
                            }
                        }
                    }
                    if (data && data.data && typeof data.data === 'string' && typeof LZString !== 'undefined') {
                        const decompressed = LZString.decompressFromBase64(data.data);
                        if (decompressed) data = JSON.parse(decompressed);
                    }

                    let parsedSchedules = null;
                    let parsedActiveName = null;

                    if (data && typeof data === 'object') {
                        if (data.allSchedules && typeof data.allSchedules === 'object') {
                            parsedSchedules = data.allSchedules;
                            parsedActiveName = data.activeScheduleName || Object.keys(data.allSchedules)[0] || '';
                        } else if (Array.isArray(data)) {
                            parsedSchedules = {};
                            data.forEach((sch, idx) => {
                                const sName = sch.name || `خشتێ ${idx + 1}`;
                                parsedSchedules[sName] = sch;
                            });
                            parsedActiveName = Object.keys(parsedSchedules)[0] || '';
                        } else {
                            if (data.teachers || data.columns || data.timetables || data.settings) {
                                const sName = data.name || activeScheduleName || 'خشتێ هاوردەکری';
                                parsedSchedules = { ...allSchedules, [sName]: data };
                                parsedActiveName = sName;
                            } else {
                                const keys = Object.keys(data);
                                if (keys.length > 0 && typeof data[keys[0]] === 'object') {
                                    parsedSchedules = data;
                                    parsedActiveName = keys[0];
                                }
                            }
                        }
                    }

                    parsedSchedules = validateAndSanitizeSchedules(parsedSchedules);

                    if (parsedSchedules && parsedActiveName && parsedSchedules[parsedActiveName]) {
                        allSchedules = parsedSchedules;
                        activeScheduleName = parsedActiveName;
                        saveData();
                        renderApp();
                        showToast('زانیاری ب سەرکەفتن هاتنه‌ ڤه‌گه‌راندن.');
                    } else if (parsedSchedules && Object.keys(parsedSchedules).length > 0) {
                        allSchedules = parsedSchedules;
                        activeScheduleName = Object.keys(parsedSchedules)[0];
                        saveData();
                        renderApp();
                        showToast('زانیاری ب سەرکەفتن هاتنه‌ ڤه‌گه‌راندن.');
                    } else {
                        throw new Error('Data format did not match expected schedule structure.');
                    }
                } catch (err) {
                    console.error('Error importing JSON:', err);
                    let errStr = (err && err.message) ? err.message : String(err);
                    showToast('هەڵە: ' + errStr, 'error');
                } finally {
                    if (document.body.contains(input)) document.body.removeChild(input);
                }
            };

            reader.onerror = () => {
                showToast('خەلەتی د خویندنا فایلی دا پەیدا بوو.', 'error');
                if (document.body.contains(input)) document.body.removeChild(input);
            };

            reader.readAsText(file);
        };

        input.click();
    }
}

// --- App Rendering ---
function renderApp(filter = '') {
    if (!activeScheduleName || !allSchedules[activeScheduleName]) return;

    // Update the school stage selection dropdown label in the first tab if exists
    const stageBtn = document.getElementById('stageSelectorBtn');
    if (stageBtn) {
        const schedule = allSchedules[activeScheduleName];
        const md = schedule?.settings?.milakData || {};
        const schoolType = md.schoolType || 'سه‌ره‌تایی 1-6';
        let label = schoolType;
        if (schoolType === 'سه‌ره‌تایی 1-6' || schoolType === 'سه‌ره‌تایی') label = 'سه‌ره‌تایی (ابتدائي) ١-٦';
        else if (schoolType === 'ناڤه‌ندی 7-9' || schoolType === 'ناڤه‌ندی') label = 'ناڤه‌ندی (متوسط) ٧-٩';
        else if (schoolType === 'بنەڕەتی 1-9') label = 'بنەڕەتی (أساسي) ١-٩';
        else if (schoolType === 'ئامادەیی زانستی' || schoolType === 'ئامادهیی') label = 'ئامادەیی زانستی (إعدادي علمي)';
        else if (schoolType === 'ئامادەیی وێژەیی') label = 'ئامادەیی وێژەیی (إعدادي أدبي)';
        stageBtn.innerHTML = `<i class="fas fa-graduation-cap me-1"></i> ${label}`;
    }

    renderDistributionTable(filter || '');
    renderAdditionalTables();
    renderStatisticsTab();
    renderNisabTab();
    if (typeof initTimetableTab === 'function') initTimetableTab();

    // Also re-render Milak Tab if the container is currently visible
    const milakPane = document.getElementById('milak-tab-pane');
    if (milakPane && milakPane.classList.contains('show')) {
        renderMilakTab();
    }
}

// --- Distribution Tab Functions ---
