async function deleteActiveSchedule() {
    const scheduleKeys = Object.keys(allSchedules);
    if (scheduleKeys.length <= 1) {
        const { isConfirmed } = await Swal.fire({
            title: `${t('delete_schedule')} "${activeScheduleName}"`,
            text: 'ئەڤە داواین خشتەیە. ئایا تە دڤێت هەمی زانیاری و ماموستایێن ڤی خشتەیی پاقژ بکەی؟',
            icon: "warning",
            showCancelButton: true,
            confirmButtonColor: '#dc3545',
            cancelButtonColor: '#6c757d',
            confirmButtonText: 'بەلێ، هەمیێ پاقژ بکە',
            cancelButtonText: t('cancel')
        });
        if (isConfirmed) {
            const sch = allSchedules[activeScheduleName];
            sch.teachers = [];
            sch.columns = [];
            sch.timetables = {};
            sch.nisab = {};
            saveData(true);
            await deleteIDBBackup();
            renderApp();
            showToast(t('toast_schedule_deleted'));
        }
        return;
    }

    const { isConfirmed } = await Swal.fire({
        title: `${t('delete_schedule')} "${activeScheduleName}"`,
        icon: "warning",
        showCancelButton: true,
        confirmButtonColor: '#dc3545',
        cancelButtonColor: '#6c757d',
        confirmButtonText: t('btn_clear_data'),
        cancelButtonText: t('cancel')
    });
    if (isConfirmed) {
        delete allSchedules[activeScheduleName];
        activeScheduleName = Object.keys(allSchedules)[0];
        saveData(true);
        await deleteIDBBackup();
        renderApp();
        showToast(t('toast_schedule_deleted'));
    }
}

async function deleteIDBBackup() {
    try {
        const db = await getIDB();
        if (db) {
            return new Promise((resolve) => {
                const tx = db.transaction(IDB_STORE, 'readwrite');
                tx.objectStore(IDB_STORE).clear();
                tx.oncomplete = () => resolve(true);
                tx.onerror = () => resolve(false);
            });
        }
    } catch (e) {
        console.warn('IDB clear warning:', e);
    }
}

