function setupSelectWithOther(selectId, otherId, value) {
    const selectElement = document.getElementById(selectId);
    const otherElement = document.getElementById(otherId);
    if (!selectElement || !otherElement) return;
    const options = Array.from(selectElement.options).map(opt => opt.value);
    const lastOtherOption = options[options.length - 1] || 'Other';
    if (value && options.includes(value)) {
        selectElement.value = value;
        otherElement.style.display = 'none'; otherElement.value = '';
    } else if (value) {
        selectElement.value = lastOtherOption;
        otherElement.style.display = 'block'; otherElement.value = value;
    } else {
        selectElement.selectedIndex = 0;
        otherElement.style.display = 'none'; otherElement.value = '';
    }
}

function populateModalSelects() {
    const certSelect = document.getElementById("teacherCertificateSelect");
    const jobSelect = document.getElementById("teacherJobTitleSelect");
    const specSelect = document.getElementById("teacherSpecializationSelect");

    if (certSelect) {
        const list = typeof t === 'function' ? t('certificates') : ["دبلوم", "بكالوريوس", "ماستر", "دكتورا", "یێن دی"];
        certSelect.innerHTML = list.map(c => `<option value="${c}">${c}</option>`).join('');
    }
    if (jobSelect) {
        const list = typeof t === 'function' ? t('job_titles') : ["رێڤه‌به‌ر", "هاریكار", "ماموستا", "ماموستایێ گرێبه‌ست", "یێن دی"];
        jobSelect.innerHTML = list.map(j => `<option value="${j}">${j}</option>`).join('');
    }
    if (specSelect) {
        const list = typeof t === 'function' ? t('specializations') : ["كوردی", "بیركاری", "ئینگلیزی", "زانست", "عربی", "یێن دی"];
        specSelect.innerHTML = list.map(s => `<option value="${s}">${s}</option>`).join('');
    }
}

function openTeacherModal(teacherId = null) {
    if (!teacherModalInstance) {
        teacherModalInstance = new bootstrap.Modal(teacherModalEl);
    }
    const schedule = allSchedules[activeScheduleName];
    const teacher = teacherId ? schedule.teachers.find(t => t.id === teacherId) : null;
    currentEditingTeacher = teacher;

    document.getElementById("teacherModalTitle").textContent = teacher ? (typeof t === 'function' ? t('teacher_info') : "نوژه‌نكرنا ماموستای") : (typeof t === 'function' ? t('btn_teacher') : "زیادکرنا ماموستای");
    const form = document.getElementById("teacherForm");
    form.reset();
    document.getElementById("teacherId").value = teacher?.id || "";
    document.getElementById("teacherName").value = teacher?.name || "";

    populateModalSelects();

    setupSelectWithOther('teacherCertificateSelect', 'teacherCertificateOther', teacher?.certificate);
    setupSelectWithOther('teacherJobTitleSelect', 'teacherJobTitleOther', teacher?.jobTitle);
    setupSelectWithOther('teacherSpecializationSelect', 'teacherSpecializationOther', teacher?.specialization);
    document.getElementById("teacherGenderSelect").value = teacher?.gender || "";
    document.getElementById("teacherStatusSelect").value = teacher?.status || "";
    document.getElementById("teacherPhone").value = teacher?.phone || "";
    document.getElementById("teacherOnLeave").checked = !!teacher?.onLeave;

    const subjectsContainer = document.getElementById("subjectsContainer");
    subjectsContainer.innerHTML = "";
    const subjects = teacher?.subjects?.length ? teacher.subjects : [{ name: "", periods: "" }];
    subjects.forEach(s => addSubjectRow(s));

    document.getElementById("addSubjectBtn").onclick = () => addSubjectRow();

    document.getElementById("teacherClassesContainer").innerHTML = '';
    updateClassInputsInModal(teacher);

    renderAvailabilityGrid(teacher);

    form.onsubmit = (ev) => { ev.preventDefault(); saveTeacherData(teacher?.id); };
    teacherModalInstance.show();
}

function addSubjectRow(subject = { name: "", periods: "" }) {
    const row = document.createElement("div");
    row.className = "d-flex gap-2 mb-2 subject-row";
    const uniqueId = 'subject_' + Date.now() + Math.random().toString(36).substr(2, 9);
    const activeSubjectsList = typeof t === 'function' ? t('specializations') : PREDEFINED_SUBJECTS;
    const otherLabel = activeSubjectsList[activeSubjectsList.length - 1] || 'Other';

    // Normalize/Translate the subject name to the active language
    const normalizedName = translateSubjectName(subject.name);
    const isOther = normalizedName && !activeSubjectsList.includes(normalizedName);

    const subjectInputHTML = `<div class="flex-grow-1">
            <select class="form-select form-select-sm subject-select shadow-sm border-0 bg-light rounded-pill px-3" onchange="document.getElementById('${uniqueId}_other').style.display = (this.value === '${otherLabel}' || this.value === 'یێن دی' || this.value === 'أخرى' || this.value === 'Other') ? 'block' : 'none'; updateClassInputsInModal(currentEditingTeacher);">
                ${activeSubjectsList.map(s => `<option value="${s}" ${normalizedName === s ? 'selected' : ''}>${s}</option>`).join('')}
            </select>
            <input type="text" class="form-control form-control-sm mt-2 subject-other-input shadow-sm border-0 bg-light rounded-pill px-3" id="${uniqueId}_other" style="display: ${isOther ? 'block' : 'none'};" placeholder="..." value="${isOther ? subject.name : ''}">
        </div>`;

    row.innerHTML = `<button type="button" class="btn btn-white text-danger btn-sm rounded-circle shadow-sm border border-light-subtle d-flex align-items-center justify-content-center" style="width: 32px; height: 32px;" onclick="this.closest('.subject-row').remove(); updateClassInputsInModal(currentEditingTeacher);" title="سڕینەوە"><i class="fas fa-times"></i></button>
                         ${subjectInputHTML}
                         <div class="input-group input-group-sm shadow-sm rounded-pill" style="width: 60px;"><input type="number" class="form-control text-center fw-bold subject-periods-input bg-light border-0 rounded-pill px-1" value="${subject.periods || ''}" placeholder="0" min="0" readonly></div>`;

    document.getElementById("subjectsContainer").appendChild(row);
}

function toggleModalLayout() {
    modalLayoutMode = (modalLayoutMode === 'vertical') ? 'horizontal' : 'vertical';
    updateClassInputsInModal(currentEditingTeacher);
}

function updateSubjectPeriodsFromClasses() {
    const subjectRows = document.querySelectorAll("#subjectsContainer .subject-row");
    
    // Get all class inputs once to avoid multiple querySelectorAll calls
    const allClassInputs = document.querySelectorAll("#teacherClassesContainer input[type='number']");
    
    subjectRows.forEach(row => {
        const subjectName = getSubjectNameFromRow(row);
        const periodsInput = row.querySelector('.subject-periods-input');
        if (!subjectName || !periodsInput) return;

        let totalPeriods = 0;
        allClassInputs.forEach(input => {
            if (input.dataset.subjectName === subjectName) {
                totalPeriods += parseInt(input.value) || 0;
            }
        });

        periodsInput.value = totalPeriods > 0 ? totalPeriods : "";
    });
}

function getSubjectNameFromRow(row) {
    const select = row.querySelector('.subject-select');
    const isOther = select.value === 'یێن دی' || select.value === 'أخرى' || select.value === 'Other' || select.value === 'شتی تر';
    return isOther ? row.querySelector('.subject-other-input').value.trim() : select.value;
}

function isSubjectAlreadyAssignedToClass(subjectName, className, currentTeacherId) {
    const schedule = allSchedules[activeScheduleName];
    for (const teacher of schedule.teachers) {
        if (teacher.id !== currentTeacherId && teacher.classes?.[className]?.[subjectName] > 0) {
            return true;
        }
    }
    return false;
}

function updateClassCardHeader(inputElement) {
    const cardBody = inputElement.closest('.card-body');
    if (!cardBody) return;
    const header = cardBody.querySelector('h6');
    const totalPeriods = Array.from(cardBody.querySelectorAll("input[type='number']")).reduce((sum, inp) => sum + (parseInt(inp.value) || 0), 0);
    let checkmark = header.querySelector('.assignment-checkmark');
    if (totalPeriods > 0) {
        if (!checkmark) header.insertAdjacentHTML('beforeend', ' <i class="fas fa-check-circle text-success ms-2 assignment-checkmark"></i>');
    } else {
        checkmark?.remove();
    }
}

// --- **MAJOR FIX in this function** ---
function updateClassInputsInModal(teacher = null) {
    const schedule = allSchedules[activeScheduleName];
    const container = document.getElementById("teacherClassesContainer");
    const currentTeacherId = parseInt(document.getElementById('teacherId').value) || nextTeacherId;

    // Step 1: Preserve the current (unsaved) values from the input fields before redrawing.
    const transientClassValues = {};
    container.querySelectorAll("input[type='number'][data-class-name]").forEach(input => {
        const { className, subjectName } = input.dataset;
        const value = parseInt(input.value, 10);
        if (value > 0) {
            if (!transientClassValues[className]) transientClassValues[className] = {};
            transientClassValues[className][subjectName] = value;
        }
    });

    // Get the current list of subjects from the subject rows.
    const subjectNames = Array.from(document.querySelectorAll("#subjectsContainer .subject-row")).map(getSubjectNameFromRow).filter(Boolean);

    // Step 2: Rebuild the HTML, using the preserved values.
    if (modalLayoutMode === 'vertical') {
        const columnsHTML = schedule.columns.map(colName => {
            let inputsHTML = subjectNames.map(subName => {
                // Step 3: Restore state. Prioritize transient (unsaved) values, then fall back to saved data.
                const value = transientClassValues?.[colName]?.[subName] || teacher?.classes?.[colName]?.[subName] || "";
                const isOtherAssigned = isSubjectAlreadyAssignedToClass(subName, colName, currentTeacherId);
                const warningIcon = isOtherAssigned ? `<i class="fas fa-exclamation-triangle text-warning ms-1" title="ئه‌ڤ بابه‌ته‌ بۆ ڤێ پولێ ژلایێ ماموستایه‌كێ دی ڤه‌ هاتیه‌ دانان"></i>` : '';
                return `<div class="d-flex align-items-center justify-content-between gap-2 bg-light rounded-pill p-1 ps-3 shadow-none border border-light-subtle"><span class="small fw-bold text-secondary-emphasis" style="font-size:0.85rem;">${subName} ${warningIcon}</span><input type="number" class="form-control form-control-sm text-center p-0 fw-bold border-0 bg-white shadow-sm rounded-pill" style="width: 45px; height: 28px; font-size: 0.95rem;" data-class-name="${colName}" data-subject-name="${subName}" value="${value}" min="0"></div>`;
            }).join('');

            if (subjectNames.length === 0) {
                inputsHTML = '<div class="text-center text-muted small p-2">زیادکرنا بابه‌ت ژ لیستا لایێ چه‌پێ</div>';
            }

            const hasAssignments = subjectNames.some(subName => (transientClassValues?.[colName]?.[subName] > 0) || (teacher?.classes?.[colName]?.[subName] > 0));
            const assignedMark = hasAssignments ? '<i class="fas fa-check-circle text-success ms-2 assignment-checkmark"></i>' : '';

            return `<div class="col-md-4 col-sm-6 mb-3"><div class="card card-body d-flex flex-column align-items-start gap-2 p-3 shadow-sm border border-light-subtle bg-white rounded-4 h-100"><h6 class="mb-2 fw-bold small text-primary d-flex align-items-center gap-2"><i class="fas fa-school text-primary-emphasis"></i><span>پولا ${colName}${assignedMark}</span></h6><div class="d-flex flex-column w-100 gap-2">${inputsHTML}</div></div></div>`;
        }).join('');
        container.innerHTML = `<div class="row g-2">${columnsHTML}</div>`;
    } else { // Horizontal Mode
        let tableContent;
        if (subjectNames.length === 0) {
            tableContent = '<tr><td colspan="100%" class="text-center text-muted p-3">زیادکرنا بابه‌ت ژ لیستا لایێ چه‌پێ</td></tr>';
        } else {
            tableContent = subjectNames.map(subName => `<tr><td class="fw-bold">${subName}</td>${schedule.columns.map(colName => {
                const value = transientClassValues?.[colName]?.[subName] || teacher?.classes?.[colName]?.[subName] || "";
                return `<td><input type="number" class="form-control form-control-sm mx-auto" style="width: 70px;" data-class-name="${colName}" data-subject-name="${subName}" value="${value}" min="0"></td>`;
            }).join('')}</tr>`).join('');
        }
        container.innerHTML = `<div class="table-responsive"><table class="table table-bordered table-sm text-center"><thead><tr><th>بابەت</th>${schedule.columns.map(c => `<th>${c}</th>`).join('')}</tr></thead><tbody>${tableContent}</tbody></table></div>`;
    }

    // Step 4: Re-attach event listeners to the new inputs.
    container.querySelectorAll("input[type='number']").forEach(input => {
        input.addEventListener('input', (event) => {
            if (modalLayoutMode === 'vertical') updateClassCardHeader(event.target);
            updateSubjectPeriodsFromClasses();
        });
    });
    updateSubjectPeriodsFromClasses();
}

function togglePeriodBlock(btn) {
    if (btn.classList.contains('btn-outline-success')) {
        btn.classList.replace('btn-outline-success', 'btn-danger');
        btn.innerHTML = '<i class="fas fa-times"></i>';
    } else {
        btn.classList.replace('btn-danger', 'btn-outline-success');
        btn.innerHTML = '<i class="fas fa-check"></i>';
    }
}

function toggleDayOffSwitch(switchEl) {
    const row = switchEl.closest('tr');
    const buttons = row.querySelectorAll('.period-block-btn');
    if (switchEl.checked) {
        buttons.forEach(btn => {
            btn.disabled = true;
            btn.classList.replace('btn-outline-success', 'btn-danger');
            btn.innerHTML = '<i class="fas fa-times"></i>';
        });
    } else {
        buttons.forEach(btn => {
            btn.disabled = false;
            btn.classList.replace('btn-danger', 'btn-outline-success');
            btn.innerHTML = '<i class="fas fa-check"></i>';
        });
    }
}

function renderAvailabilityGrid(teacher) {
    const schedule = allSchedules[activeScheduleName];
    const days = schedule.settings.workDays || ['ئێك شەمب', 'دوو شەمب', 'سێ شەمب', 'چوار شەمب', 'پێنج شەمب'];
    const periodsCount = schedule.settings.periodsPerDay || 7;
    const offDays = teacher?.offDays || [];
    const blockedPeriods = teacher?.blockedPeriods || {};

    let html = `<p class="text-muted small mb-2"><i class="fas fa-info-circle me-1 text-primary"></i>دیاری بكە كیش ل كیش روژ و وانە ماموستا نەشێت دەوامێ بكەت (إضغط على الحصة التي لا يمكن للمعلم التدريس فيها ليتم حظرها):</p>`;
    html += `<div class="table-responsive"><table class="table table-bordered text-center align-middle user-select-none">`;
    html += `<thead class="table-light"><tr><th>الروژ \\ حەسە</th>`;
    for (let p = 1; p <= periodsCount; p++) html += `<th>${p}</th>`;
    html += `</tr></thead><tbody>`;

    for (let d = 0; d < days.length; d++) {
        const day = days[d];
        const isOff = offDays.includes(day);
        html += `<tr><td class="fw-bold bg-light" style="width: 130px; padding: 5px;">
                        <div class="form-check form-switch text-start m-0">
                            <input class="form-check-input day-off-switch" type="checkbox" data-day="${day}" id="switch_${day.replace(/\s+/g, '_')}" ${isOff ? 'checked' : ''} onchange="toggleDayOffSwitch(this)">
                            <label class="form-check-label small" for="switch_${day.replace(/\s+/g, '_')}">${day}</label>
                        </div>
                     </td>`;
        for (let p = 1; p <= periodsCount; p++) {
            const isBlocked = isOff || (blockedPeriods[day] && blockedPeriods[day].includes(p));
            const btnClass = isBlocked ? 'btn-danger' : 'btn-outline-success';
            const icon = isBlocked ? '<i class="fas fa-times"></i>' : '<i class="fas fa-check"></i>';
            html += `<td style="padding: 2px;">
                            <button type="button" class="btn btn-sm ${btnClass} w-100 period-block-btn" data-day="${day}" data-period="${p}" ${isOff ? 'disabled' : ''} onclick="togglePeriodBlock(this)">
                                ${icon}
                            </button>
                         </td>`;
        }
        html += `</tr>`;
    }
    html += `</tbody></table></div>`;
    document.getElementById('teacherAvailabilityGrid').innerHTML = html;
}

function getSelectValue(selectId, otherId) {
    const select = document.getElementById(selectId);
    return select.value === 'یێن دی' ? document.getElementById(otherId).value : select.value;
}

function syncTimetablesWithTeacherQuota(schedule) {
    if (!schedule || !schedule.timetables) return;
    const teacherMap = {};
    if (Array.isArray(schedule.teachers)) {
        schedule.teachers.forEach(t => {
            teacherMap[t.name] = t;
        });
    }
    for (const className in schedule.timetables) {
        const classTimetable = schedule.timetables[className];
        if (!classTimetable) continue;
        const scheduledGroups = {};
        for (const day in classTimetable) {
            for (const period in classTimetable[day]) {
                const cell = classTimetable[day][period];
                if (cell && cell.subject) {
                    const teacherName = cell.teacher || '';
                    const key = `${cell.subject}::${teacherName}`;
                    if (!scheduledGroups[key]) scheduledGroups[key] = [];
                    scheduledGroups[key].push({ day: parseInt(day, 10), period: parseInt(period, 10) });
                }
            }
        }
        for (const key in scheduledGroups) {
            const [subjectName, teacherName] = key.split('::');
            const cells = scheduledGroups[key];
            const teacher = teacherMap[teacherName];
            const quota = (teacher && teacher.classes?.[className]?.[subjectName]) ? parseInt(teacher.classes[className][subjectName], 10) : 0;
            if (cells.length > quota) {
                cells.sort((a, b) => {
                    if (a.day !== b.day) return b.day - a.day;
                    return b.period - a.period;
                });
                const excessCount = cells.length - quota;
                for (let i = 0; i < excessCount; i++) {
                    const { day, period } = cells[i];
                    delete schedule.timetables[className][day][period];
                }
            }
        }
    }
}

function saveTeacherData(teacherId = null) {
    if (!document.getElementById("teacherName").value) return showToast(t('toast_enter_teacher_name'), "error");

    const conflicts = [];
    const targetId = teacherId ? parseInt(teacherId, 10) : nextTeacherId;
    document.querySelectorAll("#teacherClassesContainer input[type='number']").forEach(input => {
        const periods = parseInt(input.value, 10) || 0;
        if (periods > 0) {
            const { className, subjectName } = input.dataset;
            if (isSubjectAlreadyAssignedToClass(subjectName, className, targetId)) {
                conflicts.push({ className, subjectName });
            }
        }
    });

    if (conflicts.length > 0) {
        const conflictListHTML = conflicts.map(c => `<li>- ${t('col_class')} ${c.className}: ${c.subjectName}</li>`).join('');
        Swal.fire({
            title: t('subject_already_assigned_title', 'خطأ في التوزيع'),
            html: `<div class="text-start">${t('subject_already_assigned_text', 'هذه المواد تم توزيعها بالفعل في هذه الصفوف لمعلمين آخرين:')}<ul class="mt-2 mb-0">${conflictListHTML}</ul></div>`,
            icon: 'error',
            confirmButtonText: t('btn_close', 'إغلاق')
        });
        return;
    }

    const offDays = [];
    const blockedPeriods = {};
    document.querySelectorAll('.day-off-switch').forEach(sw => {
        const day = sw.dataset.day;
        if (sw.checked) {
            offDays.push(day);
        } else {
            const blockedBtns = sw.closest('tr').querySelectorAll('.period-block-btn.btn-danger');
            if (blockedBtns.length > 0) {
                blockedPeriods[day] = Array.from(blockedBtns).map(b => parseInt(b.dataset.period, 10));
            }
        }
    });

    const teacherData = {
        id: teacherId ? parseInt(teacherId, 10) : nextTeacherId,
        name: document.getElementById("teacherName").value,
        certificate: getSelectValue('teacherCertificateSelect', 'teacherCertificateOther'),
        jobTitle: getSelectValue('teacherJobTitleSelect', 'teacherJobTitleOther'),
        specialization: getSelectValue('teacherSpecializationSelect', 'teacherSpecializationOther'),
        gender: document.getElementById("teacherGenderSelect").value,
        status: document.getElementById("teacherStatusSelect").value,
        phone: document.getElementById("teacherPhone").value,
        onLeave: document.getElementById("teacherOnLeave").checked,
        offDays: offDays,
        blockedPeriods: blockedPeriods,
        subjects: [], classes: {}
    };

    const finalSubjects = {};
    document.querySelectorAll("#teacherClassesContainer input[type='number']").forEach(input => {
        const periods = parseInt(input.value, 10) || 0;
        if (periods > 0) {
            const { className, subjectName } = input.dataset;
            if (!teacherData.classes[className]) teacherData.classes[className] = {};
            teacherData.classes[className][subjectName] = periods;
            finalSubjects[subjectName] = (finalSubjects[subjectName] || 0) + periods;
        }
    });

    teacherData.subjects = Object.entries(finalSubjects).map(([name, periods]) => ({ name, periods }));

    const schedule = allSchedules[activeScheduleName];
    const teacherIndex = schedule.teachers.findIndex(t => t.id === teacherData.id);
    if (teacherIndex > -1) {
        const oldName = schedule.teachers[teacherIndex].name;
        const newName = teacherData.name;
        if (oldName !== newName && schedule.timetables) {
            for (const className in schedule.timetables) {
                for (const day in schedule.timetables[className]) {
                    for (const period in schedule.timetables[className][day]) {
                        if (schedule.timetables[className][day][period]?.teacher === oldName) {
                            schedule.timetables[className][day][period].teacher = newName;
                        }
                    }
                }
            }
        }
        schedule.teachers[teacherIndex] = teacherData;
    } else {
        schedule.teachers.push(teacherData);
        nextTeacherId++;
    }

    // --- Update Leave Table Data ---
    if (!schedule.settings) schedule.settings = {};
    if (!schedule.settings.leaveTableData) schedule.settings.leaveTableData = [];
    
    let leaveTableData = schedule.settings.leaveTableData;
    let existingIndex = leaveTableData.findIndex(row => row && row[1] === teacherData.name);
    
    if (teacherData.onLeave) {
        if (existingIndex === -1) {
            let insertIndex = leaveTableData.findIndex(row => !row || !row[1] || row[1].trim() === '');
            if (insertIndex === -1) {
                insertIndex = leaveTableData.length;
                if (!schedule.settings.leaveTableRows || insertIndex >= schedule.settings.leaveTableRows) {
                    schedule.settings.leaveTableRows = insertIndex + 1;
                }
            }
            leaveTableData[insertIndex] = [
                insertIndex + 1,
                teacherData.name,
                teacherData.specialization,
                '',
                '',
                'مۆڵەتدار (مجاز)'
            ];
        } else {
             leaveTableData[existingIndex][2] = teacherData.specialization; // update specialization
        }
    } else {
        if (existingIndex !== -1) {
            leaveTableData[existingIndex] = []; // Clear the row if they are no longer on leave
        }
    }
    // ---------------------------------

    syncTimetablesWithTeacherQuota(schedule);

    saveData();
    teacherModalInstance.hide();
    renderApp(searchInput.value);
    showToast(t('toast_teacher_saved'));
}

async function deleteTeacher(teacherId) {
    const { isConfirmed } = await Swal.fire({
        title: t('toast_teacher_deleted'), icon: "warning",
        showCancelButton: true, confirmButtonText: t('btn_clear_data'), cancelButtonText: t('cancel')
    });
    if (isConfirmed) {
        const schedule = allSchedules[activeScheduleName];
        schedule.teachers = schedule.teachers.filter(t => String(t.id) !== String(teacherId));
        syncTimetablesWithTeacherQuota(schedule);
        saveData(true);
        renderApp(searchInput.value);
        showToast(t('toast_teacher_deleted'));
    }
}

