function exportToExcel() {
    const schedule = allSchedules[activeScheduleName];
    if (!schedule || schedule.teachers.length === 0) {
        showToast('هیچ داتایه‌ك نینه‌ بۆ هنارتنێ.', 'error');
        return;
    }

    let tableToExport = document.querySelector("#tableContainer table");
    let timetableTab = document.getElementById('timetable-tab-pane');
    if (timetableTab && timetableTab.classList.contains('active')) {
        tableToExport = document.querySelector("#timetableGridTable") || document.querySelector("#timetableGridContainer table");
        // If viewing "All Classes" or "All Teachers", the container might have multiple tables. We wrap them in a temp div.
        if (document.querySelectorAll("#timetableGridContainer table").length > 1) {
            let tempWrapper = document.createElement("div");
            document.querySelectorAll("#timetableGridContainer table").forEach(tbl => tempWrapper.appendChild(tbl.cloneNode(true)));
            tableToExport = tempWrapper;
        }
    }

    if (!tableToExport) {
        showToast('هیچ خشتەیەک نیە ل ڤێرە بۆ هنارتنێ.', 'error');
        return;
    }

    let tableClone = tableToExport.cloneNode(true);
    tableClone.querySelectorAll(".no-print, .btn-delete-col").forEach(el => el.remove());

    tableClone.querySelectorAll("th, td").forEach(el => {
        el.style.border = "1pt solid windowtext";
    });

    let html = `
        <html xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:x="urn:schemas-microsoft-com:office:excel" xmlns="http://www.w3.org/TR/REC-html40">
        <head>
            <meta charset="utf-8">
            <style>
                table { border-collapse: collapse; width: 100%; direction: rtl; font-family: 'Arial', sans-serif; margin-bottom: 20px; }
                th, td { padding: 5px; text-align: center; vertical-align: middle; }
                th { background-color: #f2f2f2; font-weight: bold; }
                .text-danger { color: #dc3545; }
                .text-primary { color: #0d6efd; }
                .text-muted { color: #6c757d; font-size: 0.8em; }
                .bg-light { background-color: #f8f9fa; }
                .fw-bold { font-weight: bold; }
                .bg-dark { background-color: #212529; color: #fff; }
                .bg-secondary { background-color: #6c757d; color: #fff; }
            <\\/style>
        <\\/head>
        <body>
            <h3>${activeScheduleName}</h3>
            ${tableClone.outerHTML || tableClone.innerHTML}
        <\\/body>
        <\\/html>`;

    const blob = new Blob([html], { type: 'application/vnd.ms-excel;charset=utf-8' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = `schedule_${activeScheduleName}_${new Date().toISOString().slice(0, 10)}.xls`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
}

let classSummaryModalInstance = null;
function showClassSummary(className) {
    if (!classSummaryModalInstance) {
        classSummaryModalInstance = new bootstrap.Modal(document.getElementById('classSummaryModal'));
    }

    const schedule = allSchedules[activeScheduleName];
    document.getElementById('classSummaryModalTitle').innerText = `پوختەیا پولا ${className}`;

    let totalPeriods = 0;
    let subjectsListHTML = '<ul class="list-group list-group-flush mb-3">';

    schedule.teachers.forEach(teacher => {
        if (teacher.classes?.[className]) {
            for (const [subjectName, periods] of Object.entries(teacher.classes[className])) {
                if (periods > 0) {
                    totalPeriods += periods;
                    subjectsListHTML += `<li class="list-group-item d-flex justify-content-between align-items-center">
                            <div><i class="fas fa-book text-primary me-2"></i><strong>${subjectName}</strong><br><small class="text-muted"><i class="fas fa-user-tie me-1"></i>${teacher.name}</small></div>
                            <span class="badge bg-primary rounded-pill fs-6">${periods}</span>
                        </li>`;
                }
            }
        }
    });

    if (totalPeriods === 0) {
        subjectsListHTML += '<li class="list-group-item text-center text-muted">هیچ وانه‌یه‌ك نه‌هاتیه‌ دانان.</li>';
    }
    subjectsListHTML += '</ul>';

    const grade = getGradeFromClassName(className);
    let nisabHTML = '';
    if (grade && schedule.nisab) {
        let missingSubjects = [];
        for (const subject in schedule.nisab) {
            if (schedule.nisab[subject][grade]) {
                const required = schedule.nisab[subject][grade];
                let distributedForSubject = 0;
                schedule.teachers.forEach(t => {
                    distributedForSubject += (t.classes?.[className]?.[subject] || 0);
                });

                if (distributedForSubject !== required) {
                    const diff = distributedForSubject - required;
                    if (diff < 0) {
                        missingSubjects.push(`<span class="text-danger">${subject} (پێدڤی: ${required} | هەیە: ${distributedForSubject})</span>`);
                    } else {
                        missingSubjects.push(`<span class="text-warning">${subject} (زێدەیە ب ${diff} وانان)</span>`);
                    }
                }
            }
        }
        if (missingSubjects.length > 0) {
            nisabHTML = `<div class="alert alert-warning p-2 small mt-3"><h6 class="alert-heading fw-bold mb-1"><i class="fas fa-exclamation-triangle me-1"></i>تێبینی ژ نصابی:</h6><ul class="mb-0 ps-3">${missingSubjects.map(m => `<li>${m}</li>`).join('')}</ul></div>`;
        } else if (totalPeriods > 0) {
            nisabHTML = `<div class="alert alert-success p-2 small mt-3"><i class="fas fa-check-circle me-1"></i>هەمی وانە لدویڤ نصابی هاتینە تەواوکرن ب درستی.</div>`;
        }
    }

    const bodyHTML = `
            <div class="text-center mb-4">
                <h2 class="display-4 fw-bold text-primary mb-0">${totalPeriods}</h2>
                <p class="text-muted mb-0">کۆی وانەیێن دابەشکری</p>
            </div>
            <h6 class="fw-bold border-bottom pb-2">وردەکاری وانەکان (لدي المعلمين)</h6>
            <div style="max-height: 400px; overflow-y: auto;">
                ${subjectsListHTML}
            </div>
            ${nisabHTML}
        `;

    document.getElementById('classSummaryModalBody').innerHTML = bodyHTML;
    classSummaryModalInstance.show();
}

// --- Cloud Storage & 4-Digit PIN Mapping ---
const APP_KEYVAL_ID = 'MamostaTimetableApp_v1';

async function saveToCloud() {
    const { value: customPin, isDismissed } = await Swal.fire({
        title: 'هەڵگرتن لە هەور (Cloud Storage)',
        html: `
            <div class="mb-3 text-start">
                <label class="form-label fw-bold text-secondary">کودەکێ ٤ ڕەقەمی بنڤیسە (یان ڤالا بهێلە دا بخۆ بهێتە دروستکرن):</label>
                <input type="text" id="swalCustomPin" class="form-control form-control-lg text-center font-monospace fw-bold" placeholder="مثلاً: 4892" maxlength="4" autocomplete="off">
                <small class="text-muted d-block mt-2">ئەڤ کۆدە دێ هێتە بکارئینان بۆ ڤەگەڕاندنا داتایان ل هەر ئامێرەکێ دی.</small>
            </div>
        `,
        showCancelButton: true,
        confirmButtonText: 'هەڵگرتن',
        cancelButtonText: 'پاشگەزبوون',
        focusConfirm: false,
        preConfirm: () => {
            const inputVal = document.getElementById('swalCustomPin').value.trim();
            if (inputVal && (!/^\d{4}$/.test(inputVal))) {
                Swal.showValidationMessage('پێدڤیه‌ کود بتنێ ٤ ژمارە بت (مثل: 1234)!');
                return false;
            }
            return inputVal;
        }
    });

    if (isDismissed) return;

    let pinCode = customPin;
    if (!pinCode) {
        pinCode = Math.floor(1000 + Math.random() * 9000).toString();
    }

    Swal.fire({ title: 'تکایە چاوەڕێبە...', html: 'داتا دهێتە بارکرن بۆ هەورێ...', allowOutsideClick: false, didOpen: () => Swal.showLoading() });

    const rawData = JSON.stringify({ allSchedules, activeScheduleName });
    const compressedData = LZString.compressToBase64(rawData);
    const payload = JSON.stringify({ data: compressedData, pin: pinCode, timestamp: new Date().toISOString() });

    try {
        // Step A: Save payload to Cloud JSON Storage
        const response = await fetch("https://extendsclass.com/api/json-storage/bin", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: payload
        });
        if (!response.ok) throw new Error('Cloud storage response not OK');
        const result = await response.json();
        const binId = result.id;

        // Step B: Save 4-digit PIN mapping to KeyVal index
        try {
            await fetch(`https://keyvalue.immanuel.co/api/KeyVal/UpdateValue/${APP_KEYVAL_ID}/${pinCode}/${binId}`, {
                method: "POST"
            });
        } catch (e) {
            console.warn('KeyVal PIN mapping notice:', e);
        }

        Swal.fire({
            icon: 'success',
            title: 'ب سەرکەفتیانە هاتە هەڵگرتن',
            html: `
                <div class="p-3 bg-light rounded-4 border text-center my-2">
                    <div class="text-muted small mb-1">کودێ تە يێ ٤ ڕەقەمی يێ هەورێ:</div>
                    <div class="fs-1 text-primary fw-bold font-monospace" style="letter-spacing: 6px;">${pinCode}</div>
                </div>
                <small class="text-muted d-block mt-2">ئەڤێ کودێ ٤ ڕەقەمی ل جهەکێ پاراستی هەڵگرە بۆ ڤەگەڕاندنا داتایان.</small>
            `,
            confirmButtonText: 'کۆپی کرنا کودێ',
            showCancelButton: true,
            cancelButtonText: 'داخستن'
        }).then((res) => {
            if (res.isConfirmed) {
                navigator.clipboard.writeText(pinCode);
                showToast("کودێ ٤ ڕەقەمی هاتە کۆپیکرن");
            }
        });
    } catch (err) {
        console.error('saveToCloud Error:', err);
        Swal.fire('خەلەتی', 'نەشیا پەیوەندیێ ب راژەکارێ هەورێ بكەت.', 'error');
    }
}

async function loadFromCloud() {
    const { value: inputCode } = await Swal.fire({
        title: 'ڤەگەڕاندن ژ هەورێ',
        html: `
            <div class="mb-3 text-start">
                <label class="form-label fw-bold text-secondary">کودێ تە يێ ٤ ڕەقەمی بنڤیسە (4-digit Code):</label>
                <input type="text" id="swalLoadPin" class="form-control form-control-lg text-center font-monospace fw-bold" placeholder="مثلاً: 4892" maxlength="20" autocomplete="off">
            </div>
        `,
        showCancelButton: true,
        confirmButtonText: 'ڤەگەڕاندن',
        cancelButtonText: 'هه‌لوه‌شاندن',
        focusConfirm: false,
        preConfirm: () => {
            const v = document.getElementById('swalLoadPin').value.trim();
            if (!v) {
                Swal.showValidationMessage('پێدڤیه‌ کودێ بنڤیسی!');
                return false;
            }
            return v;
        }
    });

    if (inputCode) {
        Swal.fire({ title: 'تکایە چاوەڕێبە...', html: 'داتا دهێتە دابەزاندن...', allowOutsideClick: false, didOpen: () => Swal.showLoading() });
        try {
            let targetBinId = inputCode;

            if (/^\d{4}$/.test(inputCode)) {
                try {
                    const kvRes = await fetch(`https://keyvalue.immanuel.co/api/KeyVal/GetValue/${APP_KEYVAL_ID}/${inputCode}`);
                    if (kvRes.ok) {
                        const resolvedId = await kvRes.json();
                        if (resolvedId && typeof resolvedId === 'string' && resolvedId.length > 2) {
                            targetBinId = resolvedId;
                        }
                    }
                } catch (e) {
                    console.warn('KeyVal lookup notice:', e);
                }
            }

            const response = await fetch(`https://extendsclass.com/api/json-storage/bin/${targetBinId}`);
            if (!response.ok) throw new Error('Cloud bin not found');
            let data = await response.json();

            if (data.data) {
                const decompressed = LZString.decompressFromBase64(data.data);
                if (decompressed) data = JSON.parse(decompressed);
            }

            if (data.allSchedules && data.activeScheduleName) {
                allSchedules = validateAndSanitizeSchedules(data.allSchedules);
                activeScheduleName = sanitizeInputString(data.activeScheduleName);
                saveData();
                renderApp();
                Swal.fire('ب سەرکەفتیانە', 'زانیاری ژ هەورێ هاتنە ڤەگەڕاندن', 'success');
            } else {
                Swal.fire('خەلەتی', 'داتایێن کودێ نەدرستن یان کودێ ٤ ڕەقەمی دیار نینە.', 'error');
            }
        } catch (err) {
            console.error('loadFromCloud Error:', err);
            Swal.fire('خەلەتی', 'کودێ ٤ ڕەقەمی خەلەتە يان پەیوەندی نەما.', 'error');
        }
    }
}

