function changeTimetableView() {
    const mode = document.querySelector('input[name="ttViewMode"]:checked').value;
    const classSelect = document.getElementById('timetableClassSelect');
    const teacherSelect = document.getElementById('timetableTeacherSelect');
    const unassignedCol = document.getElementById('unassignedCol');
    const gridCol = document.getElementById('gridCol');
    const autoBtn = document.getElementById('btnAutoDistribute');
    const clearBtn = document.getElementById('btnClearTimetable');

    unassignedCol.classList.add('d-none');
    classSelect.classList.add('d-none');
    teacherSelect.classList.add('d-none');
    autoBtn.classList.add('d-none');
    clearBtn.classList.add('d-none');
    gridCol.className = 'col-md-12';

    if (mode === 'class') {
        classSelect.classList.remove('d-none');
        unassignedCol.classList.remove('d-none');
        autoBtn.classList.remove('d-none');
        clearBtn.classList.remove('d-none');
        gridCol.className = 'col-md-9';
    } else if (mode === 'teacher') {
        teacherSelect.classList.remove('d-none');
    }

    renderTimetableGrid();
}

function getDynamicFontSize(text, maxNormalChars, baseEm, minEm) {
    if (!text) return baseEm + 'em';
    const str = String(text);
    if (str.length <= maxNormalChars) return baseEm + 'em';
    const ratio = maxNormalChars / str.length;
    const scaled = Math.max(minEm, baseEm * ratio * 1.2);
    return scaled.toFixed(2) + 'em';
}

