// --- Advanced Timetable Features (Auto-Distribute & Master Prints) ---
function autoDistributeTimetableLegacy() {
    Swal.fire({
        title: 'دابەشکرنا ئۆتۆماتیکی',
        text: 'ئایا تە دڤێت سیستەم ب شێوەیەكێ ئۆتۆماتیکی هەمی وانەیێن بێ جهـ بۆ هەمی پولان دابەش بکەت؟ ڤێ چەندێ دبت دەمەکێ کێم پێدڤی بت.',
        icon: 'question',
        showCancelButton: true,
        confirmButtonText: 'بەڵی، دابەش بکە',
        cancelButtonText: 'هه‌لوه‌شاندن'
    }).then((result) => {
        if (result.isConfirmed) {
            const schedule = allSchedules[activeScheduleName];
            const days = schedule.settings.workDays || ['ئێك شەمب', 'دوو شەمب', 'سێ شەمب', 'چوار شەمب', 'پێنج شەمب'];
            const periodsCount = schedule.settings.periodsPerDay || 7;

            if (!schedule.timetables) schedule.timetables = {};

            let unassigned = [];
            // 1. Gather all required items
            schedule.columns.forEach(className => {
                if (!schedule.timetables[className]) schedule.timetables[className] = {};
                schedule.teachers.forEach(teacher => {
                    if (teacher.classes?.[className]) {
                        Object.entries(teacher.classes[className]).forEach(([subject, periods]) => {
                            for (let i = 0; i < periods; i++) {
                                unassigned.push({ className, id: `t_${teacher.id}_${subject}_${i}`, subject, teacher: teacher.name });
                            }
                        });
                    }
                });
            });

            // 2. Filter out already assigned
            unassigned = unassigned.filter(req => {
                for (let d = 0; d < days.length; d++) {
                    for (let p = 1; p <= periodsCount; p++) {
                        const item = schedule.timetables[req.className]?.[d]?.[p];
                        if (item && item.teacher === req.teacher && item.subject === req.subject && !item._matched) {
                            item._matched = true;
                            return false;
                        }
                    }
                }
                return true;
            });

            // Cleanup temp flag
            schedule.columns.forEach(className => {
                for (let d = 0; d < days.length; d++) {
                    for (let p = 1; p <= periodsCount; p++) {
                        if (schedule.timetables[className]?.[d]?.[p]) delete schedule.timetables[className][d][p]._matched;
                    }
                }
            });

            // 3. Multi-Pass Greedy Placement
            const MAX_ITERATIONS = 500; // Boosted to 500 iter for maximum conflict resolution
            let bestDistribution = null;
            let bestUnassignedCount = Infinity;
            let bestPlacedCount = 0;

            for (let iter = 0; iter < MAX_ITERATIONS; iter++) {
                // Clone the clean unassigned state
                let tempUnassigned = JSON.parse(JSON.stringify(unassigned));

                // Shuffle the tie-breaking rules
                tempUnassigned.sort((a, b) => {
                    const weightA = parseInt(schedule.teachers.find(t => t.name === a.teacher)?.classes[a.className]?.[a.subject] || 0);
                    const weightB = parseInt(schedule.teachers.find(t => t.name === b.teacher)?.classes[b.className]?.[b.subject] || 0);
                    if (weightB === weightA) return Math.random() - 0.5; // Crucial: Randomness makes iterations useful
                    return weightB - weightA;
                });

                // Clone the current timetables struct
                let tempTimetables = JSON.parse(JSON.stringify(schedule.timetables || {}));

                let currentPlacedCount = 0;
                tempUnassigned.forEach(item => {
                    let placed = false;

                    let totalTeacherPeriodsInClass = 0;
                    let teacherObj = schedule.teachers.find(t => t.name === item.teacher);
                    if (teacherObj && teacherObj.classes?.[item.className]) {
                        Object.values(teacherObj.classes[item.className]).forEach(p => totalTeacherPeriodsInClass += parseInt(p, 10));
                    }

                    let availableDaysCount = days.length;
                    if (teacherObj && teacherObj.offDays) {
                        availableDaysCount -= teacherObj.offDays.filter(day => days.includes(day)).length;
                    }
                    if (availableDaysCount <= 0) availableDaysCount = 1;
                    const maxTeacherPerDay = Math.ceil(totalTeacherPeriodsInClass / availableDaysCount);

                    let currentMaxPerDay = maxTeacherPerDay;
                    while (!placed && currentMaxPerDay <= periodsCount) {
                        let teacherDailyLoad = Array(days.length).fill(0);
                        for (let day = 0; day < days.length; day++) {
                            for (const cName of schedule.columns) {
                                for (let period = 1; period <= periodsCount; period++) {
                                    if (tempTimetables[cName]?.[day]?.[period]?.teacher === item.teacher) teacherDailyLoad[day]++;
                                }
                            }
                        }

                        let preferredDays = [];
                        for (let d = 0; d < days.length; d++) preferredDays.push(d);
                        preferredDays.sort((a, b) => {
                            if (teacherDailyLoad[a] === teacherDailyLoad[b]) return Math.random() - 0.5;
                            return teacherDailyLoad[a] - teacherDailyLoad[b];
                        });

                        for (let dayOrder = 0; dayOrder < preferredDays.length && !placed; dayOrder++) {
                            let d = preferredDays[dayOrder];
                            let dayName = days[d];
                            if (teacherObj && teacherObj.offDays && teacherObj.offDays.includes(dayName)) continue;

                            let teacherSameDayCount = 0;
                            for (let checkP = 1; checkP <= periodsCount; checkP++) {
                                if (tempTimetables[item.className]?.[d]?.[checkP]?.teacher === item.teacher) teacherSameDayCount++;
                            }
                            if (teacherSameDayCount >= currentMaxPerDay) continue;

                            let periodUsageCount = Array(periodsCount + 1).fill(0);
                            for (let day = 0; day < days.length; day++) {
                                for (let period = 1; period <= periodsCount; period++) {
                                    if (tempTimetables[item.className]?.[day]?.[period]?.teacher === item.teacher) {
                                        periodUsageCount[period]++;
                                    }
                                }
                            }

                            let preferredPeriods = [];
                            for (let p = 1; p <= periodsCount; p++) preferredPeriods.push(p);

                            preferredPeriods.sort((a, b) => {
                                if (periodUsageCount[a] === periodUsageCount[b]) return Math.random() - 0.5;
                                return periodUsageCount[a] - periodUsageCount[b];
                            });

                            for (let i = 0; i < preferredPeriods.length && !placed; i++) {
                                let p = preferredPeriods[i];

                                if (teacherObj?.blockedPeriods?.[dayName] && teacherObj.blockedPeriods[dayName].includes(p)) continue;

                                if (!tempTimetables[item.className][d]) tempTimetables[item.className][d] = {};
                                if (!tempTimetables[item.className][d][p]) {
                                    let teacherFree = true;
                                    for (const cName of schedule.columns) {
                                        if (tempTimetables[cName]?.[d]?.[p]?.teacher === item.teacher) {
                                            teacherFree = false;
                                            break;
                                        }
                                    }
                                    if (teacherFree) {
                                        tempTimetables[item.className][d][p] = {
                                            id: item.id, subject: item.subject, teacher: item.teacher
                                        };
                                        placed = true;
                                        currentPlacedCount++;
                                    }
                                }
                            }
                        }
                        if (!placed) {
                            currentMaxPerDay++; // Relax constraint and try again!
                        }
                    }
                });

                let currentUnassignedCount = tempUnassigned.length - currentPlacedCount;
                if (currentUnassignedCount < bestUnassignedCount) {
                    bestUnassignedCount = currentUnassignedCount;
                    bestPlacedCount = currentPlacedCount;
                    bestDistribution = JSON.parse(JSON.stringify(tempTimetables));

                    if (bestUnassignedCount === 0) break; // Solved perfectly!
                }
            }

            if (bestDistribution) {
                schedule.timetables = bestDistribution;
            }

            saveData();
            renderTimetableGrid();
            const remaining = bestUnassignedCount;
            Swal.fire('تم التوزيع التلقائي', `هاتنە دابەشكرن ب سەركەفتیانە: ${bestPlacedCount} وانە.<br>${remaining > 0 ? `تێبینی: ${remaining} وانە نه‌هاتنە دابەشكرن ژبەر تێكچوونا دەمان (تعارض). پێدڤیە دەستكاریێ ب دەستی بكەی.` : 'هەمی وانە بێ كێشە جهـ گرتن!'}`, remaining > 0 ? 'warning' : 'success');
        }
    });
}

function ttBuildRequiredItems(schedule) {
    const items = [];
    schedule.columns.forEach(className => {
        schedule.teachers.forEach(teacher => {
            if (!teacher.classes?.[className]) return;
            Object.entries(teacher.classes[className]).forEach(([subject, rawPeriods]) => {
                const periods = parseInt(rawPeriods, 10) || 0;
                for (let i = 0; i < periods; i++) {
                    items.push({
                        className,
                        subject,
                        teacher: teacher.name,
                        id: `t_${teacher.id}_${className}_${subject}_${i}`
                    });
                }
            });
        });
    });
    return items;
}

function ttCreateEmpty(columns) {
    const timetables = {};
    columns.forEach(className => { timetables[className] = {}; });
    return timetables;
}

function ttReqKey(item) {
    return `${item.className}|||${item.teacher}|||${item.subject}`;
}

function ttClassDayLoad(timetables, className, dayIndex) {
    return Object.keys(timetables[className]?.[dayIndex] || {}).length;
}

function ttSubjectDayLoad(timetables, className, dayIndex, subject) {
    return Object.values(timetables[className]?.[dayIndex] || {}).filter(item => item.subject === subject).length;
}

function ttTeacherDayLoad(timetables, columns, teacherName, dayIndex, periodsCount) {
    let total = 0;
    columns.forEach(className => {
        for (let p = 1; p <= periodsCount; p++) {
            if (timetables[className]?.[dayIndex]?.[p]?.teacher === teacherName) total++;
        }
    });
    return total;
}

function ttTeacherPeriodUsage(timetables, columns, teacherName, period, daysCount) {
    let total = 0;
    columns.forEach(className => {
        for (let d = 0; d < daysCount; d++) {
            if (timetables[className]?.[d]?.[period]?.teacher === teacherName) total++;
        }
    });
    return total;
}

function ttTeacherBusy(timetables, columns, teacherName, dayIndex, period, excludeClassName = null) {
    return columns.some(className => {
        if (excludeClassName && className === excludeClassName) return false;
        return timetables[className]?.[dayIndex]?.[period]?.teacher === teacherName;
    });
}

function ttTeacherCanTake(teacherObj, dayName, period) {
    if (!teacherObj) return true;
    if (teacherObj.offDays?.includes(dayName)) return false;
    if (teacherObj.blockedPeriods?.[dayName]?.includes(period)) return false;
    return true;
}

function ttPlaceItem(timetables, item, dayIndex, period) {
    if (!timetables[item.className]) timetables[item.className] = {};
    if (!timetables[item.className][dayIndex]) timetables[item.className][dayIndex] = {};
    timetables[item.className][dayIndex][period] = {
        id: item.id,
        subject: item.subject,
        teacher: item.teacher
    };
}

function ttBuildMeta(schedule, days, periodsCount, requiredItems) {
    const classLoad = {};
    const teacherLoad = {};
    const teacherAvailability = {};
    const classDailyTarget = {};
    const teacherDailyTarget = {};
    const pairLoad = {};

    requiredItems.forEach(item => {
        classLoad[item.className] = (classLoad[item.className] || 0) + 1;
        teacherLoad[item.teacher] = (teacherLoad[item.teacher] || 0) + 1;
        pairLoad[ttReqKey(item)] = (pairLoad[ttReqKey(item)] || 0) + 1;
    });

    schedule.columns.forEach(className => {
        classDailyTarget[className] = Math.ceil((classLoad[className] || 0) / Math.max(days.length, 1));
    });

    schedule.teachers.forEach(teacher => {
        let available = 0;
        days.forEach(dayName => {
            if (teacher.offDays?.includes(dayName)) return;
            for (let period = 1; period <= periodsCount; period++) {
                if (!teacher.blockedPeriods?.[dayName] || !teacher.blockedPeriods[dayName].includes(period)) {
                    available++;
                }
            }
        });
        teacherAvailability[teacher.name] = available;
        const workingDays = Math.max(days.filter(dayName => !teacher.offDays?.includes(dayName)).length, 1);
        teacherDailyTarget[teacher.name] = Math.ceil((teacherLoad[teacher.name] || 0) / workingDays);
    });

    return { classLoad, teacherLoad, teacherAvailability, classDailyTarget, teacherDailyTarget, pairLoad };
}

function ttCandidateSlots(schedule, timetables, item, days, periodsCount, meta, blockedSlotKey = null) {
    const teacherObj = schedule.teachers.find(t => t.name === item.teacher);
    const slots = [];

    for (let d = 0; d < days.length; d++) {
        const dayName = days[d];
        for (let p = 1; p <= periodsCount; p++) {
            const slotKey = `${item.className}|${d}|${p}`;
            if (blockedSlotKey && slotKey === blockedSlotKey) continue;
            if (!ttTeacherCanTake(teacherObj, dayName, p)) continue;
            if (timetables[item.className]?.[d]?.[p]) continue;
            if (ttTeacherBusy(timetables, schedule.columns, item.teacher, d, p)) continue;

            const classDayLoad = ttClassDayLoad(timetables, item.className, d);
            const subjectDayLoad = ttSubjectDayLoad(timetables, item.className, d, item.subject);
            const teacherDayLoad = ttTeacherDayLoad(timetables, schedule.columns, item.teacher, d, periodsCount);
            const teacherPeriodUsage = ttTeacherPeriodUsage(timetables, schedule.columns, item.teacher, p, days.length);

            const classTargetPenalty = classDayLoad >= (meta.classDailyTarget[item.className] || periodsCount) ? 4 : 0;
            const teacherTargetPenalty = teacherDayLoad >= (meta.teacherDailyTarget[item.teacher] || periodsCount) ? 5 : 0;

            const score =
                (classDayLoad * 6) +
                (subjectDayLoad * 10) +
                (teacherDayLoad * 8) +
                (teacherPeriodUsage * 3) +
                (classTargetPenalty * 5) +
                (teacherTargetPenalty * 6) +
                Math.random();

            slots.push({ dayIndex: d, period: p, score });
        }
    }

    slots.sort((a, b) => a.score - b.score);
    return slots;
}

function ttTryPlaceWithSwap(schedule, timetables, item, days, periodsCount, meta) {
    const directSlots = ttCandidateSlots(schedule, timetables, item, days, periodsCount, meta);
    if (directSlots.length > 0) {
        ttPlaceItem(timetables, item, directSlots[0].dayIndex, directSlots[0].period);
        return true;
    }

    const teacherObj = schedule.teachers.find(t => t.name === item.teacher);
    for (let d = 0; d < days.length; d++) {
        const dayName = days[d];
        for (let p = 1; p <= periodsCount; p++) {
            const occupied = timetables[item.className]?.[d]?.[p];
            if (!occupied) continue;
            if (!ttTeacherCanTake(teacherObj, dayName, p)) continue;
            if (ttTeacherBusy(timetables, schedule.columns, item.teacher, d, p, item.className)) continue;

            const displacedItem = {
                className: item.className,
                subject: occupied.subject,
                teacher: occupied.teacher,
                id: occupied.id
            };

            delete timetables[item.className][d][p];
            const relocationSlots = ttCandidateSlots(
                schedule,
                timetables,
                displacedItem,
                days,
                periodsCount,
                meta,
                `${item.className}|${d}|${p}`
            );

            if (relocationSlots.length > 0) {
                ttPlaceItem(timetables, displacedItem, relocationSlots[0].dayIndex, relocationSlots[0].period);
                ttPlaceItem(timetables, item, d, p);
                return true;
            }

            timetables[item.className][d][p] = occupied;
        }
    }

    return false;
}

function ttSanitizeSeed(schedule, seedTimetables, requiredItems, days, periodsCount) {
    const cleaned = ttCreateEmpty(schedule.columns);
    const requiredCounts = {};
    const usedCounts = {};

    requiredItems.forEach(item => {
        requiredCounts[ttReqKey(item)] = (requiredCounts[ttReqKey(item)] || 0) + 1;
    });

    schedule.columns.forEach(className => {
        for (let d = 0; d < days.length; d++) {
            for (let p = 1; p <= periodsCount; p++) {
                const currentItem = seedTimetables?.[className]?.[d]?.[p];
                if (!currentItem) continue;

                const candidate = {
                    className,
                    subject: currentItem.subject,
                    teacher: currentItem.teacher,
                    id: currentItem.id || `seed_${className}_${d}_${p}`
                };
                const key = ttReqKey(candidate);
                const teacherObj = schedule.teachers.find(t => t.name === candidate.teacher);

                if (!requiredCounts[key]) continue;
                if ((usedCounts[key] || 0) >= requiredCounts[key]) continue;
                if (!ttTeacherCanTake(teacherObj, days[d], p)) continue;
                if (ttTeacherBusy(cleaned, schedule.columns, candidate.teacher, d, p)) continue;

                ttPlaceItem(cleaned, candidate, d, p);
                usedCounts[key] = (usedCounts[key] || 0) + 1;
            }
        }
    });

    const consumed = {};
    const remainingItems = requiredItems.filter(item => {
        const key = ttReqKey(item);
        const consumedCount = consumed[key] || 0;
        if (consumedCount < (usedCounts[key] || 0)) {
            consumed[key] = consumedCount + 1;
            return false;
        }
        return true;
    });

    return { timetables: cleaned, remainingItems };
}

function ttRunAttempt(schedule, baseTimetables, itemsToPlace, days, periodsCount, meta, iterations) {
    let bestTimetables = JSON.parse(JSON.stringify(baseTimetables));
    let bestRemainingCount = itemsToPlace.length;

    for (let iter = 0; iter < iterations; iter++) {
        const tempTimetables = JSON.parse(JSON.stringify(baseTimetables));
        const orderedItems = [...itemsToPlace].sort((a, b) => {
            const availabilityDiff = (meta.teacherAvailability[a.teacher] || 0) - (meta.teacherAvailability[b.teacher] || 0);
            if (availabilityDiff !== 0) return availabilityDiff;

            const classDiff = (meta.classLoad[b.className] || 0) - (meta.classLoad[a.className] || 0);
            if (classDiff !== 0) return classDiff;

            const pairDiff = (meta.pairLoad[ttReqKey(b)] || 0) - (meta.pairLoad[ttReqKey(a)] || 0);
            if (pairDiff !== 0) return pairDiff;

            return Math.random() - 0.5;
        });

        let placedCount = 0;
        orderedItems.forEach(item => {
            if (ttTryPlaceWithSwap(schedule, tempTimetables, item, days, periodsCount, meta)) {
                placedCount++;
            }
        });

        const remainingCount = itemsToPlace.length - placedCount;
        if (remainingCount < bestRemainingCount) {
            bestRemainingCount = remainingCount;
            bestTimetables = JSON.parse(JSON.stringify(tempTimetables));
            if (bestRemainingCount === 0) break;
        }
    }

    return {
        timetables: bestTimetables,
        remainingCount: bestRemainingCount
    };
}

function autoDistributeTimetable() {
    Swal.fire({
        title: t('auto_distribute_title'),
        text: t('auto_distribute_prompt'),
        icon: 'question',
        showCancelButton: true,
        confirmButtonText: t('confirm'),
        cancelButtonText: t('cancel')
    }).then((result) => {
        if (!result.isConfirmed) return;

        const schedule = allSchedules[activeScheduleName];
        const days = schedule.settings.workDays || ['ئێك شەمب', 'دوو شەمب', 'سێ شەمب', 'چوار شەمب', 'پێنج شەمب'];
        const periodsCount = schedule.settings.periodsPerDay || 7;

        if (!schedule.timetables) schedule.timetables = {};

        const requiredItems = ttBuildRequiredItems(schedule);
        if (requiredItems.length === 0) {
            Swal.fire(t('result_title'), t('no_lessons_to_distribute'), 'info');
            return;
        }

        const meta = ttBuildMeta(schedule, days, periodsCount, requiredItems);
        const classCapacity = days.length * periodsCount;
        const warnings = [];

        schedule.columns.forEach(className => {
            const requiredCount = meta.classLoad[className] || 0;
            if (requiredCount > classCapacity) {
                warnings.push(`پولا ${className}: داواکاری ${requiredCount} حصەیە، بەڵام تەنها ${classCapacity} شوێن هەیە.`);
            }
        });

        schedule.teachers.forEach(teacher => {
            const requiredCount = meta.teacherLoad[teacher.name] || 0;
            const availableCount = meta.teacherAvailability[teacher.name] || 0;
            if (requiredCount > availableCount) {
                warnings.push(`ماموستا ${teacher.name}: ${requiredCount} حصەی هەیە، بەڵام تەنها ${availableCount} کاتە بەردەستە.`);
            }
        });

        const sanitizedSeed = ttSanitizeSeed(schedule, schedule.timetables || {}, requiredItems, days, periodsCount);
        const preservedPlacedCount = requiredItems.length - sanitizedSeed.remainingItems.length;

        const preserveAttempt = ttRunAttempt(
            schedule,
            sanitizedSeed.timetables,
            sanitizedSeed.remainingItems,
            days,
            periodsCount,
            meta,
            180
        );

        const rebuildAttempt = ttRunAttempt(
            schedule,
            ttCreateEmpty(schedule.columns),
            requiredItems,
            days,
            periodsCount,
            meta,
            320
        );

        const preserveRemaining = preserveAttempt.remainingCount;
        const rebuildRemaining = rebuildAttempt.remainingCount;

        const useRebuild = rebuildRemaining < preserveRemaining;
        const chosenTimetables = useRebuild ? rebuildAttempt.timetables : preserveAttempt.timetables;
        const remaining = useRebuild ? rebuildRemaining : preserveRemaining;
        const placedCount = requiredItems.length - remaining;

        schedule.timetables = chosenTimetables;
        saveData();
        renderTimetableGrid();

        let message = `هاتنە دابەشکرن: ${placedCount} حصە.<br>`;
        if (!useRebuild && preservedPlacedCount > 0) {
            message += `شوێنێن دروست یێن پێشوو پاراستن هاتن و دابەشکرن ل سەر وان بڵاڤ بوو.<br>`;
        }
        if (useRebuild) {
            message += `بۆ ئەنجامێکی باشتر، خشتەکە ژ نووە هاتە دروستکرن.<br>`;
        }

        if (remaining > 0) {
            message += `ماوە: ${remaining} حصەی نەهاتنە دابەشکرن.<br>`;
        } else {
            message += `هەمی حصە هاتنە دابەشکرن.<br>`;
        }

        if (warnings.length > 0) {
            message += `<hr><div class="text-start"><strong>هۆکارێن گومان لێکراو:</strong><ul>${warnings.slice(0, 6).map(item => `<li>${item}</li>`).join('')}</ul></div>`;
        }

        Swal.fire(t('result_title'), message, remaining > 0 ? 'warning' : 'success');
    });
}

