function changeMilakLeaveRows(delta) {
    const schedule = allSchedules[activeScheduleName];
    if (!schedule) return;
    if (!schedule.settings.milakData) schedule.settings.milakData = {};
    const current = schedule.settings.milakData.leaveRows || 3;
    schedule.settings.milakData.leaveRows = Math.max(1, current + delta);
    saveData();
    renderMilakTab();
}

function changeMilakSurplusRows(delta) {
    const schedule = allSchedules[activeScheduleName];
    if (!schedule) return;
    if (!schedule.settings.milakData) schedule.settings.milakData = {};
    const current = schedule.settings.milakData.surplusRows || 3;
    schedule.settings.milakData.surplusRows = Math.max(1, current + delta);
    saveData();
    renderMilakTab();
}

function recalculateMilakTotals() {
    let totalSections = 0;
    let totalBoys = 0;
    let totalGirls = 0;
    let totalAll = 0;

    for (let g = 1; g <= 9; g++) {
        const sections = parseInt(document.querySelector(`input[oninput*="grade_${g}_sections"]`)?.value || '0', 10) || 0;
        const boys = parseInt(document.querySelector(`input[oninput*="grade_${g}_boys"]`)?.value || '0', 10) || 0;
        const girls = parseInt(document.querySelector(`input[oninput*="grade_${g}_girls"]`)?.value || '0', 10) || 0;
        const total = boys + girls;

        totalSections += sections;
        totalBoys += boys;
        totalGirls += girls;
        totalAll += total;

        const totalCell = document.getElementById(`grade_${g}_total`);
        if (totalCell) totalCell.innerText = total || '';
    }

    const tSec = document.getElementById('total_sections');
    const tBoy = document.getElementById('total_boys');
    const tGirl = document.getElementById('total_girls');
    const tAll = document.getElementById('total_all');

    if (tSec) tSec.innerText = totalSections || '0';
    if (tBoy) tBoy.innerText = totalBoys || '0';
    if (tGirl) tGirl.innerText = totalGirls || '0';
    if (tAll) tAll.innerText = totalAll || '0';

    // Update School Lessons Total and Comparison Badge
    const schoolTotal = totalSections * 30;
    const schoolTotalEl = document.getElementById('school_lessons_total');
    if (schoolTotalEl) schoolTotalEl.innerText = schoolTotal || '0';

    const milakTotal = parseInt(document.getElementById('milak_lessons_total')?.innerText || '0', 10) || 0;
    const compContainer = document.getElementById('comparison_status_container');
    if (compContainer) {
        if (schoolTotal === milakTotal) {
            compContainer.innerHTML = '<span class="badge bg-success p-2 fs-6"><i class="fas fa-check-circle me-1"></i>' + t('matched_word', 'یەکسانن (متطابق)') + '</span>';
        } else {
            compContainer.innerHTML = '<span class="badge bg-danger p-2 fs-6"><i class="fas fa-exclamation-triangle me-1"></i>' + t('not_matched_word', 'نەیەکسانن (غير متطابق)') + '</span>';
        }
    }
}

