function exportMilakToExcel() {
    if (typeof ExcelJS === 'undefined') {
        showToast('مكتبة ExcelJS غير محملة، يرجى تحديث الصفحة', 'warning');
        return;
    }
    const schedule = allSchedules[activeScheduleName];
    if (!schedule) { showToast('هیچ خشتهیهك ههڵبژاردی نیهڵ', 'warning'); return; }

    const md = schedule.settings && schedule.settings.milakData ? schedule.settings.milakData : {};
    const fv = function (key) { return (md[key] !== undefined && md[key] !== null) ? String(md[key]) : ''; };

    showToast('کاردەکەین بۆ ئامادەکردنی فایلی ئێکسێل...', 'info');

    const TEMPLATE_FILE = 'فۆرما_رێکخستنا_میلاکی_بنەڕەت.xlsx';

    if (!window.EXCEL_TEMPLATE_BASE64) {
        showToast('فایلی نموونه‌ی ئێکسێل نەدۆزرایەوە، تکایە دڵنیابە لە هەبوونی پەڕگەی excel_template.js', 'danger');
        return;
    }

    function base64ToArrayBuffer(base64) {
        var binary_string = window.atob(base64);
        var len = binary_string.length;
        var bytes = new Uint8Array(len);
        for (var i = 0; i < len; i++) {
            bytes[i] = binary_string.charCodeAt(i);
        }
        return bytes.buffer;
    }

    Promise.resolve(base64ToArrayBuffer(window.EXCEL_TEMPLATE_BASE64))
        .then(async function (arrayBuffer) {
            const workbook = new ExcelJS.Workbook();
            await workbook.xlsx.load(arrayBuffer);
            const pezSheet = workbook.worksheets[0];
            const milakSheet = workbook.worksheets[1];

            // The two sheets (pezSheet and milakSheet) will remain separate.

            function wc(sheet, addr, val) {
                var cell = sheet.getCell(addr);
                // Check if the cell has a formula (either as a string formula or formula object)
                if (cell.value) {
                    if (typeof cell.value === 'object' && cell.value.formula) {
                        return; // Preserve formulas
                    }
                    if (typeof cell.value === 'string' && cell.value.indexOf('=') === 0) {
                        return; // Preserve formulas
                    }
                }
                cell.value = (val === undefined || val === null) ? '' : String(val);
            }

            // Fallback definitions for Excel export from Tab 1 data
            var teachersList = Array.isArray(schedule.teachers) ? schedule.teachers : [];
            var activeTeachers = teachersList.filter(function (t) { return t.name; });
            var directorTeacher = activeTeachers.find(function (t) { return t.jobTitle === 'رێڤەبەر'; }) || null;
            var assistantTeachers = activeTeachers.filter(function (t) { return t.jobTitle === 'هاریکار'; });

            var columnsList = Array.isArray(schedule.columns) ? schedule.columns : [];
            function countSectionsForGrade(g) {
                var normG = String(g);
                var kurdG = String.fromCharCode(0x06F0 + g);
                var araG = String.fromCharCode(0x0660 + g);
                return columnsList.filter(function (colName) {
                    var name = String(colName).trim();
                    return name.startsWith(normG) || name.startsWith(kurdG) || name.startsWith(araG);
                }).length;
            }

            function getStudentCountsFromTab1(g) {
                var boysSum = 0;
                var girlsSum = 0;
                var normG = String(g);
                var kurdG = String.fromCharCode(0x06F0 + g);
                var araG = String.fromCharCode(0x0660 + g);

                (schedule.settings.studentTableData || []).forEach(function (row) {
                    if (!row || !row[1]) return;
                    var className = String(row[1]).trim();
                    if (className.startsWith(normG) || className.startsWith(kurdG) || className.startsWith(araG)) {
                        boysSum += parseInt(row[3], 10) || 0;
                        girlsSum += parseInt(row[4], 10) || 0;
                    }
                });
                return { boys: boysSum, girls: girlsSum };
            }

            function getTeacherTotalLessons(t) {
                if (!t || !t.classes) return 0;
                var tot = 0;
                for (var clsKey in t.classes) {
                    var cls = t.classes[clsKey];
                    for (var subjKey in cls) {
                        tot += parseInt(cls[subjKey], 10) || 0;
                    }
                }
                return tot;
            }

            var defaultClassRooms = columnsList.length || '';

            // School Info
            wc(pezSheet, 'D6', fv('schoolName'));
            wc(pezSheet, 'D7', fv('schoolAddress'));
            wc(pezSheet, 'D8', fv('schoolGender'));
            wc(pezSheet, 'D9', fv('schoolType'));
            wc(pezSheet, 'D10', fv('schoolLanguage'));
            wc(pezSheet, 'D11', fv('schoolLocation'));
            wc(pezSheet, 'N21', fv('schoolShift'));
            pezSheet.getCell('R32').value = { formula: 'U142' };

            // Rooms (Fixed variable names to match UI: adminRooms, classRooms, labs, hasHall)
            wc(pezSheet, 'Q7', fv('adminRooms'));
            wc(pezSheet, 'S7', ''); // Reserved/Optional need
            wc(pezSheet, 'U7', ''); // Reserved/Optional note
            wc(pezSheet, 'Q8', fv('classRooms', defaultClassRooms));
            wc(pezSheet, 'S8', '');
            wc(pezSheet, 'U8', '');
            wc(pezSheet, 'Q9', fv('labs'));
            wc(pezSheet, 'S9', '');
            wc(pezSheet, 'U9', '');
            wc(pezSheet, 'Q11', fv('hasHall'));
            wc(pezSheet, 'U11', '');

            // Student counts per grade
            for (var g = 1; g <= 9; g++) {
                var r = 21 + g;
                var counts = getStudentCountsFromTab1(g);
                var defaultSections = countSectionsForGrade(g);
                var defaultBoys = counts.boys;
                var defaultGirls = counts.girls;

                wc(pezSheet, 'C' + r, fv('grade_' + g + '_sections', defaultSections !== 0 ? defaultSections : ''));
                wc(pezSheet, 'E' + r, fv('grade_' + g + '_boys', defaultBoys !== 0 ? defaultBoys : ''));
                wc(pezSheet, 'G' + r, fv('grade_' + g + '_girls', defaultGirls !== 0 ? defaultGirls : ''));
            }

            // Admin staff rows 14-18
            var staffRows = [
                { prefix: 'director', row: 14, teacher: directorTeacher },
                { prefix: 'assistant_1', row: 15, teacher: assistantTeachers[0] || null },
                { prefix: 'assistant_2', row: 16, teacher: assistantTeachers[1] || null },
                { prefix: 'assistant_3', row: 17, teacher: assistantTeachers[2] || null },
                { prefix: 'assistant_4', row: 18, teacher: assistantTeachers[3] || null }
            ];
            staffRows.forEach(function (s) {
                var tObj = s.teacher;
                var defaultName = tObj ? tObj.name : '';
                var defaultGender = tObj ? tObj.gender : '';
                var defaultCert = tObj ? tObj.certificate : '';
                var defaultSpec = tObj ? translateSubjectName(tObj.specialization) : '';
                var defaultPhone = tObj ? tObj.phone : '';
                var defaultLessons = tObj ? getTeacherTotalLessons(tObj) : '';

                wc(pezSheet, 'C' + s.row, fv(s.prefix + '_name', defaultName));
                wc(pezSheet, 'I' + s.row, fv(s.prefix + '_gender', defaultGender));
                wc(pezSheet, 'J' + s.row, fv(s.prefix + '_cert', defaultCert));
                wc(pezSheet, 'L' + s.row, fv(s.prefix + '_spec', defaultSpec));
                wc(pezSheet, 'N' + s.row, fv(s.prefix + '_lessons', defaultLessons !== '' && defaultLessons !== 0 ? defaultLessons : ''));
                wc(pezSheet, 'O' + s.row, fv(s.prefix + '_birth', ''));
                wc(pezSheet, 'R' + s.row, fv(s.prefix + '_phone', defaultPhone));
                wc(pezSheet, 'U' + s.row, fv(s.prefix + '_notes', ''));
            });

            // Special education
            wc(pezSheet, 'A35', fv('special_boys'));
            wc(pezSheet, 'D35', fv('special_girls'));
            wc(pezSheet, 'O35', fv('special_lessons'));
            wc(pezSheet, 'J35', fv('has_special_teacher'));
            wc(pezSheet, 'S35', fv('no_special_teacher'));
            wc(pezSheet, 'J37', fv('has_social_supervisor'));
            wc(pezSheet, 'O37', fv('no_social_supervisor'));

            // On-leave teachers (rows 42-46) - Section 4
            var teachersList = Array.isArray(schedule.teachers) ? schedule.teachers : [];
            var activeTeachers = teachersList.filter(t => t.name);
            var onLeaveTeachers = activeTeachers.filter(t => t.onLeave);
            var leaveData = Array.isArray(md.milakLeaveData) ? md.milakLeaveData : [];
            for (var i = 0; i < 5; i++) {
                var lr = leaveData[i] || {};
                var olt = onLeaveTeachers[i] || null;

                var defaultName = olt ? olt.name : '';
                var defaultGender = olt ? olt.gender : '';
                var defaultCert = olt ? olt.certificate : '';
                var defaultSpec = olt ? translateSubjectName(olt.specialization) : '';

                var nameVal = lr.name !== undefined && lr.name !== '' ? lr.name : defaultName;
                var genderVal = lr.gender !== undefined && lr.gender !== '' ? lr.gender : defaultGender;
                var certVal = lr.cert !== undefined && lr.cert !== '' ? lr.cert : defaultCert;
                var specVal = lr.spec !== undefined && lr.spec !== '' ? lr.spec : defaultSpec;

                var lr_row = 42 + i;
                wc(pezSheet, 'B' + lr_row, nameVal);
                wc(pezSheet, 'G' + lr_row, genderVal);
                wc(pezSheet, 'H' + lr_row, certVal);
                wc(pezSheet, 'J' + lr_row, specVal);
                wc(pezSheet, 'L' + lr_row, lr.leaveType || '');
                wc(pezSheet, 'O' + lr_row, lr.leaveFrom || '');
                wc(pezSheet, 'R' + lr_row, lr.leaveTo || '');
                wc(pezSheet, 'U' + lr_row, lr.adminOrder || '');
            }

            // Surplus / deficit (rows 51-55)
            var surplusData = Array.isArray(md.milakSurplusData) ? md.milakSurplusData : [];
            for (var j = 0; j < 5; j++) {
                var sr = surplusData[j] || {};
                var sr_row = 51 + j;
                wc(pezSheet, 'B' + sr_row, sr.name || '');
                wc(pezSheet, 'K' + sr_row, sr.spec || '');
                wc(pezSheet, 'P' + sr_row, sr.subject || '');
                wc(pezSheet, 'T' + sr_row, sr.lessons || '');
            }

            // Supervisor
            wc(pezSheet, 'A58', fv('supervisorOpinion'));
            wc(pezSheet, 'R61', fv('supervisorName'));
            wc(pezSheet, 'R62', fv('supervisorDate'));

            // --- Teacher List in milakSheet ---
            var MILAK_SUBJECTS_ORDERED = ['ئایین', 'ز.كوردی', 'ز.عه‌ره‌بی', 'ز.ئێنگلیزی', 'بیركاری', 'زانست', 'كومه‌لایه‌تی', 'كارامه‌یی', 'ده‌روونزانی', 'كومپیوته‌ر', 'هونه‌ر', 'وه‌رزش'];
            var teachers = Array.isArray(schedule.teachers) ? schedule.teachers : [];
            var activeTeachers = teachers.filter(function (t) { return t && t.name && t.name.trim() !== ''; });

            // Clear rows 4-75 for writable columns in milakSheet (Columns B to H and V)
            var clearCols = ['B', 'C', 'D', 'E', 'F', 'G', 'H', 'I', 'J', 'K', 'L', 'M', 'N', 'O', 'P', 'Q', 'R', 'S', 'T', 'V'];
            for (var cr = 4; cr <= 75; cr++) {
                clearCols.forEach(function (col) {
                    var cell = milakSheet.getCell(col + cr);
                    if (cell.value && typeof cell.value === 'object' && cell.value.formula) {
                        return; // Keep formula
                    }
                    cell.value = '';
                });
            }

            function getSubjectLessons(teacher, subjName) {
                if (!teacher.classes) return '';
                var total = 0;
                var found = false;
                var milakIdx = SUBJECT_MAP[subjName.trim()];
                Object.values(teacher.classes).forEach(function (cls) {
                    if (!cls) return;
                    Object.entries(cls).forEach(function (entry) {
                        var kIdx = SUBJECT_MAP[entry[0].trim()];
                        if (kIdx !== undefined && milakIdx !== undefined && kIdx === milakIdx) {
                            total += parseInt(entry[1], 10) || 0;
                            found = true;
                        }
                    });
                });
                return found && total > 0 ? total : '';
            }

            activeTeachers.forEach(function (teacher, idx) {
                var tr = 4 + idx;
                if (tr > 75) return;

                // Read correct values from milakData just like the UI does
                var tName = teacher.name || '';
                var tJobTitle = teacher.jobTitle || t('job_titles')[2];
                var tGender = fv('teacher_gender_' + teacher.id, teacher.gender || '');
                var tCert = fv('teacher_cert_' + teacher.id, teacher.certificate || '');
                var tSpec = fv('teacher_spec_' + teacher.id, teacher.specialization || '');
                var tBirth = fv('teacher_birth_' + teacher.id, '');
                var tPhone = fv('teacher_phone_' + teacher.id, teacher.phone || '');
                var tNotes = fv('teacher_note_' + teacher.id, '');

                // Write text values to milakSheet
                wc(milakSheet, 'B' + tr, tName);
                wc(milakSheet, 'C' + tr, tJobTitle);
                wc(milakSheet, 'D' + tr, tGender);
                wc(milakSheet, 'E' + tr, tCert);
                wc(milakSheet, 'F' + tr, tSpec);
                wc(milakSheet, 'G' + tr, tBirth); // "ئاكنجيبوون" Column / Date of birth in UI
                wc(milakSheet, 'H' + tr, tPhone);
                wc(milakSheet, 'V' + tr, tNotes);

                // Write subject lessons numbers (Columns I to T)
                MILAK_SUBJECTS_ORDERED.forEach(function (subj, si) {
                    var col = String.fromCharCode(73 + si); // Column I is index 73 (I, J, K, ...)
                    var val = getSubjectLessons(teacher, subj);
                    if (val !== '') {
                        var cell = milakSheet.getCell(col + tr);
                        if (cell.value && typeof cell.value === 'object' && cell.value.formula) {
                            return;
                        }
                        cell.value = Number(val);
                    }
                });
            });
            // Write buffer & Download
            const buffer = await workbook.xlsx.writeBuffer();
            const blob = new Blob([buffer], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
            const url = URL.createObjectURL(blob);
            const link = document.createElement('a');
            link.href = url;
            link.download = 'فۆرما_رێکخستنا_میلاکی_بنەڕەت.xlsx';
            document.body.appendChild(link);
            link.click();
            document.body.removeChild(link);
            URL.revokeObjectURL(url);
            showToast('✅ تم تصدير البيانات إلى نموذج Excel الأصلي بنجاح', 'success');
        })
        .catch(function (err) {
            console.error('exportMilakToExcel error:', err);
            showToast('⚠️ خه‌تهیهك ڕوویدا: ' + err.message, 'danger');
        });
}

function exportLeaveTeachersToExcel() {
    // Just trigger the same main export which populates all sheets in one file
    exportMilakToExcel();
}

function exportToExcel() {
    // Redirect weekly timetable export to call the unified export
    // to export all 3 sheets in one single file!
    exportMilakToExcel();
}